/* Spec v10.1 narrative: five parts around the Failure → Data core. renderCurrentPlatform wraps every page with the story bar, bridge line, source line and pager. */
const cpMoney = n => new Intl.NumberFormat('vi-VN',{style:'currency',currency:'USD',minimumFractionDigits:2,maximumFractionDigits:2}).format(n);
const cpNumber = n => new Intl.NumberFormat('vi-VN',{maximumFractionDigits:2}).format(n);
const cpLink = (url,label) => `<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(label)} <span aria-hidden="true">↗</span></a>`;
const cpButton = (href,label,secondary=false) => `<a class="cp-button${secondary?' cp-secondary':''}" href="${href}">${label}<span aria-hidden="true">→</span></a>`;
const cpKicker = s => `<p class="cp-kicker">${s}</p>`;
const cpHeader = (tag,title,desc) => `<header class="cp-heading">${cpKicker(tag)}<h1>${title}</h1><p>${desc}</p></header>`;
const cpSection = (tag,title,body) => `<section class="cp-section">${cpKicker(tag)}<h2>${title}</h2>${body}</section>`;
const cpNote = s => `<p class="cp-note">${s}</p>`;
const cpMetric = (n,label,small='') => `<div class="cp-metric"><strong>${n}</strong><span>${label}</span>${small?`<small>${small}</small>`:''}</div>`;
function cpIcon(name){const paths={camera:'M3 7h5l2-3h4l2 3h5v13H3z M16 13a4 4 0 1 1-8 0 4 4 0 0 1 8 0',data:'M4 5c0-4 16-4 16 0s-16 4-16 0v14c0 4 16 4 16 0V5 M4 12c0 4 16 4 16 0',sim:'M12 2 22 7v10l-10 5-10-5V7z M2 7l10 5 10-5 M12 12v10',train:'M5 4h14v16H5z M8 8h8 M8 12h8 M8 16h5 M2 8h3 M19 8h3 M2 16h3 M19 16h3',gate:'M4 12l5 5L20 6 M3 22h18',robot:'M7 8h10v10H7z M12 8V3 M9 12h1 M14 12h1 M3 10v6 M21 10v6 M9 18v4 M15 18v4'};return `<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.data}"/></svg>`;}
function cpFigure(file,title,source,label){return `<figure class="cp-figure"><a href="assets/platform/${file}" target="_blank" rel="noopener" aria-label="Mở hình gốc: ${esc(title)}"><img src="assets/platform/${file}" alt="${esc(title)}" loading="lazy" width="1200"></a><figcaption><span>${title}</span>${cpLink(source,label+' · hình gốc')}</figcaption></figure>`;}
const cpUsd = n => Math.abs(n)<0.005?'Hòa vốn':(n>0?'+':'−')+'$'+new Intl.NumberFormat('vi-VN',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Math.abs(n));
const cpWide = (heads,rows) => table(heads,rows).replace('class="table-wrap"','class="table-wrap cp-wide"');
function cpStepDetail(index){const s=CURRENT_PLATFORM.steps[index];return `<div class="cp-detail-label">0${index+1} / ${s.title}</div><div class="cp-detail-grid"><div><span>Đầu vào</span><p>${s.input}</p></div><div><span>Xử lý</span><p>${s.process}</p></div><div><span>Đầu ra</span><p>${s.output}</p></div></div><p class="cp-detail-gate">${cpIcon('gate')}${s.gate}</p>`;}

/* Five-part story: every page sits in one part; the wrapper adds the story bar, bridge line, source line and pager. */
const CP_PARTS=[
 {id:'problem',no:'1',label:'Vấn đề',routes:['overview','product']},
 {id:'core',no:'2',label:'Lõi Failure → Data',routes:['architecture','engine']},
 {id:'plug',no:'3',label:'Phần cắm',routes:['sources','learning']},
 {id:'evidence',no:'4',label:'Bằng chứng',routes:['validation','business']},
 {id:'deploy',no:'5',label:'Triển khai',routes:['roadmap','outcomes','team']},
 {id:'ref',no:'·',label:'Tham khảo',routes:['research'],reference:true}
];
const CP_PAGE_META={
 overview:{answers:'DENSO đau ở đâu, và sản phẩm là gì trong một câu.',lead:'Bắt đầu từ vấn đề của DENSO và sản phẩm trong một câu.'},
 product:{answers:'vòng 8 bước chạy thế nào, mỗi vòng để lại tài sản gì, phần nào là lõi.',lead:'Vòng 8 bước, tài sản tích lũy sau mỗi vòng, lõi và phần cắm.'},
 architecture:{answers:'Failure → Data khác gì “thu thêm teleop”, Mulligan và DISEIL; claim nào giữ, claim nào không.',lead:'Lõi khác gì cách làm hiện có, và claim nào được giữ.',src:'mục 0, 1.2, 6.4–6.9, 13'},
 engine:{answers:'từ một lỗi đến quyết định dữ liệu: thứ tự phép kiểm, bảng quyết định, chọn theo chi phí.',lead:'Thử 12 bước trên từng kịch bản lỗi: lỗi nào được tiêu ngân sách dữ liệu.',src:'mục 6.1–6.15'},
 sources:{answers:'nguồn dữ liệu nào cắm vào lõi, mỗi nguồn mang nhãn gì và được đếm thế nào.',lead:'Các nguồn dữ liệu cắm vào lõi và cách đếm demo gốc.',src:'mục 1.1, 2.3, 4.1–4.4'},
 learning:{answers:'Ψ₀ học gì, đội fine-tune gì, bộ điều khiển nào chạy task chính.',lead:'Ψ₀ học gì, đội fine-tune gì, và rủi ro bộ điều khiển V3.',src:'mục 2.1–2.4, 7.3, 7.4, 10'},
 validation:{answers:'PoC kiểm điều gì: nhánh, giả thuyết, tiêu chí 3 cấp của BTC và thống kê.',lead:'Các nhánh đối chứng, giả thuyết HS/HT/HD và tiêu chí 3 cấp của BTC.',src:'mục 3, 7.1–7.8'},
 business:{answers:'giá trị đo bằng chỉ số nào, và lợi ích đô-la nhạy với giả định nào.',lead:'Chỉ số giá trị chính, công thức rút gọn và độ nhạy chi phí.',src:'mục 8.1–8.4'},
 roadmap:{answers:'12 tuần chia thành 6 sprint, cổng G0–G6 và ai làm gì.',lead:'6 sprint, cổng G0–G6, hạn V3 và phân công 5 người.'},
 outcomes:{answers:'mở rộng từ L0 tới L4: lõi giữ gì, adapter đổi gì.',lead:'Từ 1 task trong sim tới nhiều nhà máy: lõi giữ, adapter đổi.'},
 team:{answers:'ai thực hiện, đã có minh chứng gì, giữ vai nào trong kế hoạch.',lead:'5 người, minh chứng hiện có và vai trong kế hoạch.'},
 research:{answers:'nguồn công nghệ, tiền lệ Failure → Data và hướng mở rộng V2D, DreamDojo.',lead:'Ψ₀/SIMPLE, tiền lệ Failure → Data và hướng mở rộng V2D, DreamDojo.'}
};
const cpPartOf = id => CP_PARTS.find(p=>p.routes.includes(id));
function cpStoryBar(id){const cur=cpPartOf(id);return `<nav class="cp-story" aria-label="Mạch trình bày 5 phần"><ol>${CP_PARTS.filter(p=>!p.reference).map(p=>`<li><a href="#${p.routes[0]}"${p===cur?' class="is-current" aria-current="step"':''}><span>${p.no}</span>${p.label}</a></li>`).join('')}</ol>${cur.reference?'<span class="cp-story-ref">Đang ở: Tham khảo</span>':''}</nav>`;}
function cpBridge(id){const i=chapters.findIndex(c=>c[0]===id),prev=i>0?chapters[i-1]:null;return `<p class="cp-bridge">${prev?`<span>Trang trước: <a href="#${prev[0]}">${esc(prev[1])}</a></span>`:'<span>Mở đầu mạch trình bày</span>'}<span aria-hidden="true">→</span><span>Trang này trả lời: <b>${CP_PAGE_META[id].answers}</b></span></p>`;}
function cpPager(id){const i=chapters.findIndex(c=>c[0]===id),last=i===chapters.length-1,ni=last?chapters.findIndex(c=>c[0]==='architecture'):i+1,next=chapters[ni],prev=i>0?chapters[i-1]:null;return `<nav class="cp-pager" aria-label="Chuyển trang">${prev?`<a class="cp-pager-back" href="#${prev[0]}"><span aria-hidden="true">←</span> Quay lại · ${esc(prev[1])}</a>`:'<span></span>'}<a class="cp-pager-next" href="#${next[0]}"><span class="cp-pager-label">${last?'Quay về lõi':'Tiếp theo'} · ${String(ni+1).padStart(2,'0')}</span><strong>${esc(next[1])}</strong><small>${CP_PAGE_META[next[0]].lead}</small><b aria-hidden="true">→</b></a></nav>`;}
function cpPositioning(){return `<figure class="cp-positioning"><figcaption>Định vị · spec v10.1 mục 0</figcaption><blockquote>Humanoid Data Flywheel là quy trình vận hành có kiểm toán cho vòng lỗi → dữ liệu: loại lỗi hệ thống trước khi tiêu tiền vào dữ liệu, chọn giữa nhiều loại can thiệp theo chi phí thật kể cả chi phí chẩn đoán, và xuất <b>khuyến nghị thu dữ liệu định lượng</b> cho DENSO.</blockquote><p>PoC kiểm lại trên G1 toàn thân với Ψ₀ xem “nhắm lỗi thắng rải đều” có còn đúng khi tính đủ chi phí.</p></figure>`;}

/* 01 · Vấn đề & ý tưởng */
function cpOverview(){return `<section class="cp-hero"><div>${cpKicker('DENSO FACTORY HACKS · HUMANOID & ROBOT')}<h1>Robot lỗi. Biết sửa gì trước.<br><em>Rồi mới mua thêm dữ liệu.</em></h1><p>Đề xuất cho DENSO Việt Nam: dạy humanoid một công đoạn với ít demo hơn, và sau mỗi lần robot làm hỏng, biết nên sửa hệ thống hay bổ sung loại dữ liệu nào, bổ sung bao nhiêu, tốn bao nhiêu.</p><div class="cp-actions">${cpButton('#architecture','Xem khác biệt của lõi')}${cpButton('#product','Vòng data flywheel',true)}</div><span class="cp-hero-by">Đội ilovephysicalintelligence · Spec v10.1 · Chưa thực nghiệm</span></div><div class="cp-hero-visual"><span class="cp-photo-label">RECIPE ĐẦU TIÊN · Ψ₀ + SIMPLE / G1</span><img src="assets/platform/psi0-sim-data.png" alt="Figure gốc Ψ₀: các cảnh humanoid thao tác và tạo dữ liệu trong mô phỏng" width="1912" height="766"><div class="cp-hero-caption"><strong>Cúi → gắp → nâng → đặt, toàn thân G1</strong><span>Một task trong mô phỏng trước; robot thật nghiệm thu riêng sau PoC.</span>${cpLink(CURRENT_PLATFORM.sources.psi,'Nguồn hình: Ψ₀')}</div></div></section>`+cpPositioning()+`<div class="cp-metrics">${cpMetric('≥ 50%','Thành công với ít demo','Cấp 1 BTC · báo ở mức 10% và 25% dữ liệu')}${cpMetric('≥ 75%','Khi giảm ≥ 30% demo teleop','Cấp 2 BTC · mục tiêu PoC, chưa đo')}${cpMetric('≥ 70%','Trên biến thể chưa train','Cấp 3 BTC · kèm khuyến nghị thu dữ liệu định lượng')}</div>`+cpSection('VẤN ĐỀ CỦA DENSO','Dạy humanoid tốn công, và mỗi kỹ năng mới lại thu từ đầu.',`<div class="cp-four">${[['01','Đưa humanoid vào nhà máy khó','DENSO Việt Nam muốn phát triển humanoid, nhưng đưa vào dây chuyền là thách thức lớn.'],['02','Training lâu, chưa đủ chính xác','Mỗi lần robot hỏng, đội đoán nguyên nhân bằng video và log rồi thường chọn thu thêm teleop.'],['03','Chưa có mô hình thu dữ liệu chuẩn','Đề bài gọi tên “DENSO Data Model”: quy trình thu và kiểm dữ liệu để dạy robot hiệu quả.'],['04','Kỹ năng mới thu lại từ đầu','Không giữ lại được tình huống, lỗi, dữ liệu đã kiểm và chi phí của lần dạy trước.']].map(r=>`<article class="cp-plain"><span class="cp-index">${r[0]}</span><h3>${r[1]}</h3><p>${r[2]}</p></article>`).join('')}</div>${cpNote('Theo đề “Efficient Humanoid Training & DENSO Data Model”: 1 kỹ năng thao tác trong simulation trong 3 tháng, so sánh ít nhất 2 phương pháp train và lượng dữ liệu cần. Kịch bản pain point chi tiết của DENSO đang chờ gửi.')}`)+cpSection('AI ĐANG ĐAU','Khi policy hỏng, “thu thêm teleop” là lựa chọn mặc định',table(['Người dùng','Điều đang đau'],[['Kỹ sư robot learning','Đoán nguyên nhân lỗi bằng mắt; không có cách nào chắc hơn “thu thêm teleop”'],['Kỹ sư simulation','Không biết nên sinh dữ liệu ở vùng điều kiện nào; sinh đều thì tốn GPU mà không trúng chỗ yếu'],['Kỹ sư data','Biến thể bị đếm như demo gốc; dữ liệu test lộ vào train; đơn vị và thời gian lệch giữa nguồn'],['Operator teleop','Thu lặp lại tình huống robot đã làm được; mỗi lượt tốn thời gian reset'],['Chủ công đoạn tại nhà máy','Không có con số: cần bao nhiêu công để robot đạt chuẩn khi đổi linh kiện, khay, ánh sáng']]))+cpSection('SẢN PHẨM TRONG MỘT CÂU','Không phải model mới. Không phải bộ dữ liệu.',`<blockquote class="cp-oneliner">Một nền tảng giúp đội robot biết, sau mỗi lần humanoid làm hỏng một task, nên sửa hệ thống hay bổ sung loại dữ liệu nào, bổ sung bao nhiêu, và lần sửa đó tốn bao nhiêu so với chất lượng nhận được.</blockquote><div class="cp-three"><article class="cp-card"><span class="cp-index">LÕI</span><h3>Failure → Data</h3><p>Chẩn đoán lỗi, chọn can thiệp theo chi phí, cổng kiểm và sổ chi phí. Đây là phần được chấm là đóng góp.</p></article><article class="cp-card"><span class="cp-index">PHẦN CẮM</span><h3>Ψ₀ + SIMPLE / G1</h3><p>Model, simulator và robot là recipe đầu tiên cắm vào lõi; thay được khi đổi task, robot hoặc nhà máy.</p></article><article class="cp-card"><span class="cp-index">ĐẦU RA CHO DENSO</span><h3>Khuyến nghị định lượng</h3><p>Thu dữ liệu loại nào, bao nhiêu, tốn bao nhiêu, kèm SOP thu và kiểm dữ liệu (DENSO Data Model).</p></article></div>`)+cpNote('Bản PowerPoint Pitch v10 chưa cập nhật theo spec v10.1: deck vẫn ghi “≥ 80% / 50 lượt” và dẫn bằng lợi ích đô-la. Website này theo spec v10.1. Mọi con số là mục tiêu hoặc giả định; chưa có kết quả Ψ₀ hay robot thật của đội.');}

/* 02 · Vòng data flywheel */
function cpWorkflow(){const steps=CURRENT_PLATFORM.steps;return `<section class="cp-flow" aria-labelledby="cp-flow-title"><div class="cp-flow-head"><div>${cpKicker('MỘT VÒNG FLYWHEEL')}<h2 id="cp-flow-title">Từ lỗi của policy đến release dữ liệu đã qua cổng</h2></div><span class="cp-status">Đặc tả, chưa chạy</span></div><p class="cp-hint">Chọn một bước để xem đầu vào, cách xử lý, đầu ra và ràng buộc. Bước 3–4 là lõi Failure → Data.</p><div class="cp-flow-steps cp-eight" role="group" aria-label="Tám bước của một vòng">${steps.map((s,i)=>`<button type="button" data-cp-step="${i}" aria-pressed="${i===0}" aria-controls="cp-step-detail"${i===2||i===3?' class="cp-core-step"':''}><span class="cp-step-no">0${i+1}${i===2||i===3?' · LÕI':''}</span>${cpIcon(s.icon)}<strong>${s.title}</strong><small>${s.short}</small></button>`).join('')}</div><div class="cp-return">↶ Sổ chi phí cập nhật tỉ lệ sửa được → vòng sau chọn can thiệp theo số đo, không chỉ theo đơn giá</div><div id="cp-step-detail" class="cp-step-detail" aria-live="polite">${cpStepDetail(0)}</div></section>`;}
function cpProduct(){return cpHeader('VẤN ĐỀ / VÒNG DATA FLYWHEEL','Tám bước một vòng.<br>Mỗi vòng để lại tài sản dùng lại.','Một vòng bắt đầu từ lỗi của policy trong mô phỏng và kết thúc bằng release dữ liệu, policy đã qua cổng và sổ chi phí. Bước chẩn đoán và quyết định là lõi, trình bày chi tiết ở phần 2.')+cpWorkflow()+cpSection('TÀI SẢN SAU MỖI VÒNG','Vì sao gọi là flywheel',`<ol class="cp-assets">${[['Thư viện tình huống và lỗi','Điều kiện nào đã thử, policy nào hỏng ở bước nào.'],['Thống kê “can thiệp nào sửa được lỗi nào”','Tỉ lệ sửa được đo có đối chứng với policy cha. Là tài sản cần đo ở L1; ở L0 tín hiệu sớm lấy từ F-ACT.'],['Dữ liệu đã QA, có lineage','Trộn lại được cho vòng sau và cho task sau; không đếm biến thể là demo gốc.'],['Scorer và định nghĩa bước','Khung chấm từng bước cho loại task gắp, đặt, mang.'],['Sổ chi phí','Biết trước một lần cải thiện tốn bao nhiêu phút người và GPU-giờ.']].map(a=>`<li><strong>${a[0]}</strong><p>${a[1]}</p></li>`).join('')}</ol>${cpNote('Vòng càng quay, phần đoán càng ít, chi phí mỗi điểm % thành công càng giảm. Đó là lời hứa cần đo được, không phải mặc định.')}`)+cpSection('LÕI VÀ PHẦN CẮM','Ψ₀ + SIMPLE / G1 là recipe đầu tiên cắm vào lõi',table(['Thuộc lõi · không đổi khi đổi model, robot, simulator','Thuộc phần cắm · adapter thay được'],[['Mô hình dữ liệu: episode, release, trace, evidence card, sổ chi phí','Model và trainer: Ψ₀, ACT, Diffusion Policy'],['Lineage, chia tập, QA chung','Simulator: SIMPLE (Isaac Sim, MuJoCo), sau này cell thật'],['Khung scorer từng bước, phân loại lỗi','Robot: G1 trong sim, sau này G1 thật hoặc robot khác'],['Chuỗi phép kiểm chẩn đoán và bảng quyết định','Bộ sinh dữ liệu: motion planning, kiểu MimicGen, V2D'],['Chọn can thiệp theo ngân sách, thống kê tỉ lệ sửa được','Nguồn teleop: thiết bị VR, bàn điều khiển'],['Sổ chi phí, cổng kiểm, báo cáo','Định nghĩa task cụ thể và vị từ của scorer']]))+`<div class="cp-extensions"><a href="#sources"><span>PHẦN CẮM · DỮ LIỆU</span><strong>Teleop, sim và prior video người đi qua cùng QA và lineage</strong></a><a href="#research"><span>MỞ RỘNG SAU POC</span><strong>V2D cho video công nhân · DreamDojo cho đánh giá</strong></a></div>`+cpSection('BÀN GIAO SAU 12 TUẦN','Bốn đầu ra khớp đề của BTC',`<div class="cp-four">${['SOP thu và kiểm dữ liệu · Data Core + SOP là DENSO Data Model','Báo cáo so sánh ACT, Diffusion Policy, Ψ₀ kèm kết quả HS, HT, HD','Demo kỹ năng: video rollout trong SIMPLE trên tập holdout','Khuyến nghị thu dữ liệu định lượng kèm sổ chi phí (Cấp 3)'].map((s,i)=>`<div class="cp-small-card"><b>0${i+1}</b><strong>${s}</strong></div>`).join('')}</div>${cpNote('Ψ₀, SIMPLE, V2D và DreamDojo là công nghệ có sẵn. Đóng góp của đội là lõi Failure → Data và phép đo xem lõi có đáng tiền; hiệu quả phải chứng minh bằng PoC.')}`);}

/* 03 · Failure → Data: khác biệt */
function cpCompareTable(){const mark=(cls,label)=>s=>`<span class="cp-mark ${cls}">${label}</span> ${s}`,Y=mark('cp-yes','Có'),N=mark('cp-no','Không'),U=mark('cp-unseen','Chưa thấy'),P=mark('cp-part','Một phần'),G=mark('cp-goal','Mục tiêu, chưa đo');
return cpWide(['Tiêu chí','Thu thêm teleop','Mulligan (2026)','DISEIL (2026)','Humanoid Data Flywheel · L0'],[
 ['<b>Chọn dữ liệu theo lỗi</b>',N('Thu thêm theo cảm nhận, thường rải đều'),Y('Chọn trạng thái đầu của vòng thu tại lỗi đã thấy và trạng thái chưa thử'),Y('Tìm điểm policy không tin cậy, gom lỗi thành nhóm, chọn lỗi cần expert làm mẫu'),G('Kiểm lại kiểu Mulligan / DISEIL (HTa); không phải điểm mới')],
 ['<b>Kiểm lỗi hệ thống trước khi thu dữ liệu</b>',N('Lỗi controller, đồng bộ, calibration dễ bị coi là thiếu dữ liệu'),U('trong phạm vi đã tra'),P('Kiểm khả thi trước khi tốn công expert; chưa thấy kiểm controller, đồng bộ, calibration'),G('5 phép kiểm trên log stack WBC và kiểm khả thi, trước mọi chi tiêu dữ liệu')],
 ['<b>Nhiều loại can thiệp trên một thước đo chi phí, kể cả chi phí chẩn đoán</b>',N('Một loại: thu teleop'),U('trong phạm vi đã tra'),U('trong phạm vi đã tra'),G('Sim quanh lỗi, teleop correction, dữ liệu phục hồi; chi phí chẩn đoán cộng vào tổng')],
 ['<b>Cổng kiểm + sổ chi phí</b>',N('Thường train lại rồi xem kết quả'),U('sổ chi phí theo vòng'),U('sổ chi phí theo vòng'),G('Cổng dev có A/A test; sổ có cờ ước tính và thực đo')],
 ['<b>Đầu ra là khuyến nghị thu dữ liệu định lượng</b>',N('Đầu ra là thêm demo'),U('đầu ra chính là policy được cải thiện'),U('đầu ra chính là policy được cải thiện'),G('Bước 10–11 cộng sổ chi phí, khớp Cấp 3 của BTC')]
]);}
function cpTraceChips(id){const s=CP_SCENARIOS[id],d=CP_DIAG[s.diag],stop=CP_CHECKS.findIndex(c=>c.id===s.stop);return `<article class="cp-run-example ${d.budget?'is-data':'is-system'}"><span class="cp-badge">Level ${s.level}</span><h3>${s.label}</h3><p>${s.story}</p><ol class="cp-chips" aria-label="Các phép kiểm đã chạy">${CP_CHECKS.slice(0,stop+1).map((c,i)=>{const skip=c.id==='visual'&&s.level===0,hit=i===stop;return `<li class="${hit?'is-hit':skip?'is-skip':''}">B${c.step} · ${c.name}: ${hit?cpHitText(c,s):skip?'bỏ qua (Level 0)':'đạt'}</li>`;}).join('')}</ol><p class="cp-verdict-line">→ <strong>${d.name}</strong>: ${d.action}.</p><p class="cp-verdict-budget">${d.budget?'Có tiêu ngân sách dữ liệu':'Không tiêu ngân sách dữ liệu'}</p></article>`;}
function cpArchitecture(){return cpHeader('LÕI / FAILURE → DATA','Loại lỗi hệ thống trước.<br>Rồi mới chi tiền cho dữ liệu.','Ý “thu dữ liệu bắt đầu từ chỗ policy thất bại” đã có tiền lệ. Phần khác biệt hẹp hơn và đo được: kiểm hệ thống trước, chọn giữa nhiều loại can thiệp trên một thước đo chi phí, xuất khuyến nghị định lượng.')+cpPositioning()+cpSection('BA KHÁC BIỆT CHÍNH','Đóng góp là cách ghép các phép kiểm thành quy trình ra quyết định có ghi chi phí',`<div class="cp-three cp-diff"><article class="cp-card"><span class="cp-index">01 · HỆ THỐNG TRƯỚC</span><h3>Kiểm lỗi hệ thống trước khi thu dữ liệu</h3><p>Năm phép kiểm chỉ cần log trên stack WBC: thiếu tín hiệu, bám lệnh, độ trễ, đồng bộ ảnh–state, camera chuẩn; sau đó kiểm khả thi bằng planner. Lỗi hệ thống thành phiếu sửa và phải đo lại baseline.</p><b>8 trong 11 chẩn đoán không tiêu ngân sách dữ liệu</b></article><article class="cp-card"><span class="cp-index">02 · NHIỀU CAN THIỆP, MỘT THƯỚC ĐO</span><h3>Chọn can thiệp theo chi phí thật</h3><p>Sinh sim quanh điểm lỗi, teleop correction và dữ liệu phục hồi được so trên cùng sổ USD và giờ công. Chi phí chẩn đoán (rollout kiểm, giờ kỹ sư) cộng vào tổng chi phí của nhánh C.</p><b>g = (n_eff / N) × tỉ lệ sửa được, xếp theo g / chi phí</b></article><article class="cp-card"><span class="cp-index">03 · CỔNG + SỔ → KHUYẾN NGHỊ</span><h3>Đầu ra là khuyến nghị định lượng</h3><p>Ứng viên chỉ được dùng khi qua cổng dev có A/A test. Mỗi mục sổ có cờ ước tính hoặc thực đo để đo sai số dự báo chi phí. Đầu ra cho DENSO: thu loại nào, bao nhiêu, tốn bao nhiêu.</p><b>Mục tiêu ở L0, chưa đo</b></article></div>`)+cpSection('SO VỚI CÁCH LÀM HIỆN CÓ','Ghi “Có” khi tiền lệ đã làm; ô của đội là mục tiêu, chưa đo',cpCompareTable()+cpNote('“Chưa thấy” nghĩa là chưa thấy trong phạm vi đã tra ngày 22/10/2026, không khẳng định tiền lệ không có. Mulligan còn dùng dữ liệu lỗi để học value function; PoC không dùng dữ liệu lỗi làm tín hiệu train, đó là hướng L1. Các tiền lệ khác: DAgger / HG-DAgger, IntervenGen, MimicGen, DataMIL, CUPID (trang 12).'))+cpSection('VÍ DỤ CHẠY QUA','Hai lỗi giống nhau ở bề ngoài, hai kết cục khác nhau',`<div class="cp-two">${cpTraceChips('coverage')}${cpTraceChips('sync')}</div><p class="cp-hint">Minh họa thứ tự kiểm ở spec mục 6.4–6.9; kết quả đạt/không đạt là giả định, chưa phải kết quả chạy.</p><div class="cp-actions">${cpButton('#engine','Thử thêm kịch bản ở trang 04',true)}</div>`)+cpSection('RANH GIỚI CLAIM','Giữ gì, không claim gì',`<div class="cp-compare"><article><span>Giữ</span><h3>Quy trình và phép đo</h3><ul><li>Quy trình kiểm hệ thống trước, rồi chọn giữa nhiều loại can thiệp bằng một thước đo tiền và giờ công gồm chi phí chẩn đoán.</li><li>Phép đo xem quy trình có đáng tiền: HS, HTa, HTb, HD với tiêu chí chốt trước holdout.</li><li>Data Core cộng SOP là DENSO Data Model theo tên đề.</li></ul></article><article><span>Không claim</span><h3>Những điều chưa có hoặc không phải của đội</h3><ul><li>Thuật toán học máy mới: mọi thành phần đều có tiền lệ.</li><li>Nhắm theo lỗi là điểm mới: HT là kiểm lại kiểu Mulligan / DISEIL.</li><li>Kết quả trên robot thật: số PoC chỉ trong mô phỏng, lợi ích của sim có thể bị phóng đại.</li><li>Tiết kiệm tiền mặt: sổ đo giá trị nguồn lực theo đơn giá giả định.</li></ul></article></div>`);}

/* 04 · Thuật toán 12 bước */
const CP_ALGO=[
 {phase:'Chạy & gán nhãn',cls:'run',steps:[[1,'Chạy','Policy × 90 điều kiện dev → trace'],[2,'Gán nhãn','Bước hỏng đầu tiên k, kiểu lỗi'],[3,'Gom cụm sơ bộ','Theo (k, kiểu lỗi, mức); tối đa 5 đại diện']]},
 {phase:'Chẩn đoán',cls:'diag',steps:[[4,'Kiểm hệ thống','Tín hiệu, bám lệnh, độ trễ, đồng bộ, camera'],[5,'Kiểm khả thi','Planner chuẩn từ cùng điều kiện đầu'],[6,'Khoanh vùng','s_k từ trạng thái chuẩn ở đầu bước k'],[7,'Kiểm thị giác','Level 1–2: đổi hình ảnh về mức chuẩn'],[8,'Kiểm vùng phủ','Trong miền train? Khoảng cách kNN'],[9,'Chẩn đoán cụm','Theo đa số đại diện; hòa thì kỹ sư quyết']]},
 {phase:'Quyết định',cls:'decide',steps:[[10,'Đề xuất & định lượng','Can thiệp, số lượng, chi phí ước tính'],[11,'Chọn theo ngân sách','Xếp g/c; hòa thì bước hỏng sớm trước']]},
 {phase:'Thu & kiểm',cls:'gate',steps:[[12,'Thu, QA, train, cổng','Release mới, ứng viên, tỉ lệ sửa được đo có đối chứng']]}
];
const CP_CHECKS=[
 {id:'signal',step:4,name:'Đủ tín hiệu',rule:'Trace đủ trường; camera không mất khung',pass:'Đủ trường',hit:'Thiếu tín hiệu'},
 {id:'track',step:4,name:'Bám lệnh WBC',rule:'Sai số lệnh gửi − trạng thái đo ≤ τ_track, riêng thân trên và thân dưới',pass:'Trong ngưỡng',hit:'Sai số > τ_track'},
 {id:'latency',step:4,name:'Độ trễ suy luận',rule:'Phân vị 99 độ trễ chu kỳ ≤ τ_lat',pass:'Trong ngưỡng',hit:'p99 > τ_lat'},
 {id:'sync',step:4,name:'Đồng bộ ảnh – state',rule:'Lệch thời gian lớn nhất giữa khung ảnh và state ≤ τ_sync',pass:'Trong ngưỡng',hit:'Lệch > τ_sync'},
 {id:'camera',step:4,name:'Camera chuẩn',rule:'Hash nội tham số và tư thế camera trùng bản tham chiếu G0',pass:'Trùng tham chiếu',hit:'Khác bản tham chiếu'},
 {id:'feasible',step:5,name:'Planner chuẩn làm được',rule:'Planner trong env WBC thành công từ cùng điều kiện đầu',pass:'Planner làm được',hit:'Planner cũng thất bại'},
 {id:'localize',step:6,name:'Bắt đầu đúng thì làm được?',rule:'s_k sau M = 10 lượt từ trạng thái chuẩn ở đầu bước k; ngưỡng τ_k = 0,8',pass:'s_k < 0,8: kỹ năng bước k yếu, đi tiếp',hit:'s_k ≥ 0,8: lỗi do bước trước'},
 {id:'visual',step:7,name:'Hình ảnh chuẩn thì làm được?',rule:'Chỉ Level 1–2: giữ vật lý, đưa ánh sáng và vật liệu về Level 0',pass:'Vẫn lỗi: không phải nhận thức',hit:'Hình chuẩn thì thành công'},
 {id:'domain',step:8,name:'Trong miền train',rule:'Phần vật lý của điều kiện nằm trong [min, max] của tập train',pass:'Trong miền',hit:'Ngoài miền train'},
 {id:'coverage',step:8,name:'Gần dữ liệu đã có?',rule:'d = khoảng cách trung bình tới K = 5 điều kiện train gần nhất, so với τ_cov',pass:'',hit:''}
];
const CP_DIAG={
 unknown:{name:'CHƯA RÕ',cond:'Thiếu tín hiệu',action:'Thu thêm bằng chứng, sửa logging',budget:false,type:'report'},
 controller:{name:'LỖI CONTROLLER',cond:'Sai số bám lệnh > τ_track',action:'Sửa cấu hình stack WBC và ánh xạ khớp, rồi chạy lại baseline',budget:false,type:'system'},
 runtime:{name:'LỖI RUNTIME',cond:'Độ trễ > τ_lat',action:'Sửa pipeline suy luận, rồi chạy lại baseline',budget:false,type:'system'},
 sync:{name:'LỖI ĐỒNG BỘ',cond:'Lệch thời gian ảnh và state > τ_sync',action:'Sửa đồng bộ cảm biến, rồi chạy lại baseline của policy hiện tại',budget:false,type:'system'},
 calib:{name:'LỖI CALIBRATION',cond:'Tham số hoặc tư thế camera khác bản tham chiếu',action:'Sửa calibration camera, rồi chạy lại baseline',budget:false,type:'system'},
 infeasible:{name:'KHÔNG KHẢ THI',cond:'Planner chuẩn thất bại',action:'Sửa cảnh hoặc thu hẹp miền task, ghi lại',budget:false,type:'system'},
 badstate:{name:'TRẠNG THÁI ĐẦU XẤU',cond:'s_k ≥ τ_k',action:'Dữ liệu phục hồi: 1 đoạn mỗi lỗi, bắt đầu từ trạng thái lỗi đã lưu; tối đa 10 đoạn mỗi cụm',budget:true,type:'data'},
 perception:{name:'NHẬN THỨC',cond:'Kiểm thị giác thành công',action:'Ghi nhận và báo cáo; tăng cường thị giác đã cố định cho mọi nhánh',budget:false,type:'report'},
 ood:{name:'NGOÀI MIỀN',cond:'Điều kiện ngoài miền train',action:'Ghi nhận và báo cáo số lỗi theo mức; vùng lấy mẫu trong miền train sẽ rỗng',budget:false,type:'report'},
 coverage:{name:'THIẾU VÙNG PHỦ',cond:'Trong miền, d > τ_cov',action:'Sinh 20 rollout sim đạt QA mỗi lỗi, trong bán kính τ_cov quanh điều kiện lỗi và trong miền train; tối đa 200 rollout (10 lỗi) mỗi cụm',budget:true,type:'data'},
 weak:{name:'KỸ NĂNG YẾU',cond:'Trong miền, d ≤ τ_cov',action:'Teleop correction ở bước k, 1 mỗi lỗi, tối đa 10 mỗi cụm; demo mâu thuẫn lân cận chỉ ghi vào báo cáo',budget:true,type:'data'}
};
const CP_SCENARIOS={
 sync:{short:'Camera trễ',label:'Camera trễ',level:0,story:'Gắp hụt ở bước 2: ảnh đến muộn so với state nên policy nhìn thấy vật ở vị trí cũ.',stop:'sync',diag:'sync'},
 calib:{short:'Lệch calibration',label:'Lệch calibration camera',level:0,story:'Đặt lệch khay đều về một phía; tư thế camera khác cấu hình chuẩn đã hash ở G0.',stop:'camera',diag:'calib'},
 controller:{short:'Lệnh không bám',label:'Lệnh không bám',level:0,story:'Action chunk hướng đúng vật nhưng tay và thân không đi theo lệnh gửi tới WBC.',stop:'track',diag:'controller'},
 unknown:{short:'Log thiếu khung',label:'Log thiếu khung hình',level:0,story:'Episode lỗi nhưng trace mất khung camera và thiếu trường trạng thái đo.',stop:'signal',diag:'unknown'},
 infeasible:{short:'Vật ngoài tầm với',label:'Vật ngoài tầm với',level:0,story:'Vật nằm ở vị trí mà cả planner chuẩn cũng không gắp được.',stop:'feasible',diag:'infeasible'},
 badstate:{short:'Trạng thái xấu do bước trước',label:'Đặt lệch vì bước trước để lại trạng thái xấu',level:0,story:'Lỗi ở bước 5 (đặt), nhưng vật đã bị gắp lệch ở bước 2. Bắt đầu đúng từ đầu bước 5 thì policy đặt được.',stop:'localize',diag:'badstate'},
 perception:{short:'Ánh sáng lạ',label:'Ánh sáng lạ',level:1,story:'Lỗi ở Level 1 (ánh sáng mạnh). Giữ nguyên vật lý, đưa ánh sáng về Level 0 thì policy làm được.',stop:'visual',diag:'perception'},
 ood:{short:'Vật ngoài miền train',label:'Vật ngoài miền train',level:2,story:'Level 2 đặt vật ở vị trí ngoài khoảng [min, max] của điều kiện train.',stop:'domain',diag:'ood'},
 coverage:{short:'Gắp trượt ở vùng chưa có dữ liệu',label:'Gắp trượt khi đổi vị trí vật',level:0,story:'Vật ở vị trí trong miền train nhưng xa các demo đã có; tay đóng mà không giữ được vật ở bước 2.',stop:'coverage',diag:'coverage'},
 weak:{short:'Gắp trượt ở vùng đã có dữ liệu',label:'Gắp trượt dù đã có demo gần đó',level:0,story:'Vị trí vật nằm giữa các demo đã có, policy vẫn trượt: dữ liệu mâu thuẫn hoặc tình huống khó.',stop:'coverage',diag:'weak'}
};
const CP_FAULT_ALIASES={binding:'calib'};
const CP_TYPE_LABEL={system:'Phiếu sửa hệ thống',data:'Đề xuất dữ liệu → bước 10–11',report:'Ghi vào báo cáo'};
function cpHitText(c,s){return c.id==='coverage'?(s.diag==='coverage'?'d > τ_cov':'d ≤ τ_cov'):c.hit;}
function cpFault(kind){const id=CP_FAULT_ALIASES[kind]||kind,s=Object.prototype.hasOwnProperty.call(CP_SCENARIOS,id)?CP_SCENARIOS[id]:null;if(!s)throw new RangeError('Kịch bản lỗi không tồn tại.');const d=CP_DIAG[s.diag];let stopped=false;
 const rows=CP_CHECKS.map((c,i)=>{let state,text;if(stopped){state='off';text='Không chạy: đã có chẩn đoán';}else if(c.id===s.stop){state='hit';text=cpHitText(c,s);stopped=true;}else if(c.id==='visual'&&s.level===0){state='skip';text='Bỏ qua: lỗi ở Level 0';}else{state='pass';text=c.pass;}const tag={pass:'✓ Đạt',hit:'✕ Dừng',skip:'– Bỏ qua',off:'·'}[state];return `<li class="cp-check is-${state}" style="--i:${i}"><span class="cp-check-step">Bước ${c.step}</span><div><strong>${c.name}</strong><small>${c.rule}</small></div><em>${tag} · ${text}</em></li>`;}).join('');
 return `<div class="cp-trace-head"><span class="cp-badge">Level ${s.level}</span><h3>${s.label}</h3><p>${s.story}</p></div><ol class="cp-checks" aria-label="Các phép kiểm theo thứ tự">${rows}</ol><div class="cp-verdict ${d.budget?'is-data':'is-system'}" style="--i:${CP_CHECKS.length}"><div><span>Chẩn đoán</span><strong>${d.name}</strong><p>${CP_TYPE_LABEL[d.type]}</p></div><div><span>Can thiệp</span><p>${d.action}</p></div><div><span>Ngân sách dữ liệu</span><b>${d.budget?'Có tiêu ngân sách dữ liệu':'Không tiêu ngân sách dữ liệu'}</b></div></div>`;}
function cpAlgoDiagram(){return `<section class="cp-algo" aria-label="Sơ đồ 12 bước của một vòng">${CP_ALGO.map(p=>`<div class="cp-algo-phase cp-algo-${p.cls}"><span class="cp-algo-label">${p.phase}</span><ol>${p.steps.map(s=>`<li value="${s[0]}"><b>Bước ${s[0]}</b><strong>${s[1]}</strong><small>${s[2]}</small></li>`).join('')}</ol></div>`).join('')}<p class="cp-algo-exit">Thoát sớm: bước 4–5 phát hiện lỗi hệ thống hoặc không khả thi → phiếu sửa, không vào bước 10–11. NHẬN THỨC, NGOÀI MIỀN và CHƯA RÕ → báo cáo. Sau bước 12, tỉ lệ sửa được được cập nhật và vòng mới dùng tập cổng mới.</p></section>`;}
function cpFaultTool(){const first=Object.keys(CP_SCENARIOS)[0];return `<section class="cp-decision" aria-labelledby="cp-fault-title"><div class="cp-flow-head"><div>${cpKicker('CÔNG CỤ TƯƠNG TÁC')}<h2 id="cp-fault-title">Chọn một kịch bản lỗi, xem từng phép kiểm</h2></div><span class="cp-status">Minh họa logic, chưa phải kết quả chạy</span></div><p class="cp-hint">Kết quả đạt/không đạt của từng kịch bản là giả định để minh họa thứ tự kiểm. Ngưỡng τ thật được hiệu chỉnh ở G0–G1 từ demo teleop thành công.</p><div class="cp-choice" role="group" aria-label="Kịch bản lỗi">${Object.entries(CP_SCENARIOS).map(([k,s])=>`<button type="button" data-cp-fault="${k}" aria-pressed="${k===first}" aria-controls="cp-fault-result">${s.short}</button>`).join('')}</div><div id="cp-fault-result" aria-live="polite">${cpFault(first)}</div></section>`;}
function cpSelection(){const ex=[['Gắp trượt, vị trí vật mới','THIẾU VÙNG PHỦ','Sinh sim quanh lỗi',14],['Đặt lệch do gắp lệch','TRẠNG THÁI ĐẦU XẤU','Dữ liệu phục hồi',4],['Gắp trượt ở vùng đã phủ','KỸ NĂNG YẾU','Teleop correction',6]];
 return cpSection('BƯỚC 10–11 / CHỌN CAN THIỆP THEO CHI PHÍ','Lợi ích kỳ vọng chia chi phí, trong ngân sách vòng',`<div class="cp-formula"><div><span>Lợi ích kỳ vọng của cụm j</span><strong>g<sub>j</sub> = (n_eff<sub>j</sub> / N<sub>dev</sub>) × f̄<sub>t</sub></strong><small>n_eff = min(m_j, L_t = 10) · N_dev = 90 · f̄_t là trung bình tỉ lệ sửa được của loại can thiệp t, prior Beta(1, 1). Đơn vị: điểm % thành công trên dev.</small></div><div><span>Thứ tự chọn</span><strong>g<sub>j</sub> / c<sub>j</sub> giảm dần</strong><small>c_j từ đơn giá trong sổ chi phí, tính trên n_eff lỗi. Chọn lần lượt tới khi hết ngân sách vòng; hòa thì cụm có bước hỏng sớm hơn đi trước.</small></div></div>`+cpWide(['Cụm (minh họa)','Chẩn đoán','Loại can thiệp t','m_j lỗi','n_eff','g_j ở vòng 1 (f̄ = 0,5)'],ex.map(r=>{const n=Math.min(r[3],10);return [r[0],r[1],r[2],r[3],n,'≈ '+cpNumber(Math.round(n/90*0.5*1000)/10)+' điểm %'];}))+`<div class="cp-three"><article class="cp-card"><span class="cp-index">VÒNG 1</span><h3>Chỉ là xếp theo đơn giá</h3><p>g_j và c_j cùng tỉ lệ với n_eff, nên g/c = f̄_t / (N_dev × đơn giá mỗi lỗi của loại t), không phụ thuộc cụm. Với prior đều, loại rẻ nhất trong các loại chẩn đoán cho phép đi trước. Chẩn đoán quyết định loại nào được phép, L_t quyết định số lượng. Có unit test cho tính chất này.</p></article><article class="cp-card"><span class="cp-index">TỪ VÒNG 2</span><h3>Tỉ lệ sửa được đo có đối chứng</h3><p>Lấy điều kiện mới quanh lỗi (bán kính τ_cov / 2, tối đa 5 mỗi lỗi, 30 mỗi cụm). Chạy policy cha và ứng viên, mỗi bên ≥ 3 lượt. fixed = làm tròn(n × (p_ứng viên − p_cha)), kẹp trong [0, n]; α += fixed, β += n − fixed. Tránh hồi quy về trung bình khi chạy lại đúng điều kiện cũ.</p></article><article class="cp-card"><span class="cp-index">DỪNG KHI</span><h3>Hết đáng tiền</h3><p>Hết ngân sách; đề xuất tốt nhất có g/c dưới 1 điểm % mỗi $100; hai vòng liền không qua cổng dev; hoặc đủ số vòng khai: Ψ₀ 1 vòng (tối đa 2), F-ACT 5–8 vòng.</p></article></div>`+cpNote('Minh họa logic, chưa phải kết quả chạy: số lỗi m_j là giả định; chi phí c_j chỉ có sau khi đo đơn giá thật ở G0–G3. Với Ψ₀ chỉ 1 vòng mặc định, f_t được đo nhưng chưa kịp dùng lại; bằng chứng “flywheel học” lấy từ F-ACT trên ACT (trang 07).'));}
function cpEngine(){return cpHeader('LÕI / THUẬT TOÁN 12 BƯỚC','Từ một lỗi<br>đến một quyết định dữ liệu.','Mỗi vòng chạy 12 bước cố định. Thứ tự kiểm không đổi: hệ thống trước, dữ liệu sau. Thuật toán đề xuất, kỹ sư quyết định; mọi lần ghi đè phải có lý do trong evidence card.')+cpAlgoDiagram()+cpFaultTool()+cpSection('BƯỚC 9 / BẢNG QUYẾT ĐỊNH','11 chẩn đoán; chỉ 3 chẩn đoán được tiêu ngân sách dữ liệu',cpWide(['Chẩn đoán','Điều kiện','Can thiệp','Tiêu ngân sách dữ liệu?'],Object.values(CP_DIAG).map(d=>[`<b>${d.name}</b>`,d.cond,d.action,d.budget?'<span class="cp-mark cp-yes">Có</span>':'<span class="cp-mark cp-no">Không</span>']))+cpNote('Một lỗi đã có chẩn đoán hệ thống thì không đi tiếp vào nhánh dữ liệu. Sau khi sửa hệ thống phải chạy lại baseline của policy hiện tại, vì phép đo cũ không còn giá trị. Tăng cường thị giác là phần cố định của recipe cho mọi nhánh, không phải can thiệp riêng của C.'))+cpSelection()+`<details class="cp-details"><summary>Tham số mặc định (spec mục 6.15)</summary>${table(['Tham số','Giá trị khởi đầu','Hiệu chỉnh'],[['R · đại diện mỗi cụm','5','Cố định'],['M · lượt chạy từ trạng thái chuẩn','10','Cố định'],['τ_k','0,8','Cố định'],['K · láng giềng gần nhất','5','Cố định'],['τ_track, τ_sync','Phân vị 99 trên demo teleop thành công','G1'],['τ_lat · camera tham chiếu','Phân vị 99 lần chạy chuẩn · hash tham số camera','G0'],['τ_cov','Phân vị 95 khoảng cách kNN leave-one-out trong train','G1'],['L_t · số lỗi xử lý tối đa mỗi cụm','10','Cố định'],['Tập cổng mỗi vòng','90 điều kiện mới, ≥ 3 lượt mỗi điều kiện','Cố định'],['Hồi quy cho phép','max(5%, sàn A/A)','Sàn A/A đo ở G3'],['Ngưỡng dừng g/c','1 điểm % mỗi $100','Chốt trước vòng 1']])}</details>`;}

/* 05 · Dữ liệu & nguồn: counting units (spec 4.1) */
function cpCountingUnits(){return cpSection('PHẦN CẮM VÀO LÕI / ĐƠN VỊ ĐẾM','Nguồn nào cũng qua cùng QA; chỉ demo người được đếm là demo gốc',table(['Đơn vị','Định nghĩa','Tính là demo gốc?'],[['Demo teleop','Một episode người điều khiển, đạt QA và scorer','Có'],['Teleop correction','Đoạn người điều khiển bắt đầu từ một trạng thái lỗi của policy','Có, đếm riêng và cộng vào giờ operator'],['Rollout sim','Episode do planner sinh rồi thực thi trong simulator, đạt scorer','Không; ghi demo hoặc điều kiện gốc'],['Biến thể','Bản sửa từ một episode khác (đổi vị trí, đổi hình ảnh)','Không; luôn trỏ về episode cha'],['Rollout đánh giá','Episode chạy policy để chấm','Không bao giờ vào dữ liệu train']])+cpNote('r_demo = 1 − (số demo teleop + correction mà nhánh dùng) / D*. QA bắt buộc: timestamp, đồng bộ ảnh–state ≤ 1 khung, giới hạn khớp theo URDF, bước nhảy action, scorer, lineage và chia tập theo hạt giống điều kiện. Mẫu bị loại vẫn giữ cùng lý do và chi phí.'));}

function cpSources(){return cpHeader('PHẦN CẮM / DỮ LIỆU VÀ NGUỒN','Bốn nguồn dữ liệu.<br>Bốn cách sử dụng rõ ràng.','Nguồn rẻ chỉ có ích khi biết nó cung cấp nhãn gì, học thành phần nào và cần kiểm tra gì trước khi dùng.')+`<div class="cp-four cp-data-types"><article class="cp-card">${cpIcon('camera')}<h2>Human ego</h2><p>Video từ góc nhìn người thao tác.</p><b>Học biểu diễn thao tác</b><small>RGB; pose/token nếu dataset có. PoC kế thừa prior qua checkpoint.</small></article><article class="cp-card">${cpIcon('camera')}<h2>Video người bên ngoài</h2><p>Video raw quay người và vật.</p><b>Tái dựng → grounding robot</b><small>Không mặc định là egocentric hoặc có robot action.</small></article><article class="cp-card">${cpIcon('robot')}<h2>Robot teleop</h2><p>Người điều khiển robot làm task.</p><b>Học hành động task</b><small>RGB + state + action đồng bộ, đúng robot/controller.</small></article><article class="cp-card">${cpIcon('sim')}<h2>Synthetic</h2><p>Dữ liệu sinh theo loại mô hình.</p><b>Sim có nhãn ≠ video dự đoán</b><small>Sim: state/action thực thi. World model: video tương lai.</small></article></div>`+cpCountingUnits()+cpDatasetExamples()+cpSection('VIDEO-TO-DATA / NVIDIA','Video người raw thành dữ liệu robot như thế nào?',cpFigure('v2d-overview.png','Từ human demonstration đến dữ liệu robot có cơ sở vật lý',CURRENT_PLATFORM.sources.v2d,'NVIDIA V2D')+`<div class="cp-three"><article class="cp-plain"><b>01 · Tái dựng</b><p>Clip → depth, mask, mesh, pose và quỹ đạo người–vật.</p></article><article class="cp-plain"><b>02 · Grounding</b><p>Retarget sang robot mục tiêu, thực thi và kiểm trong mô phỏng.</p></article><article class="cp-plain"><b>03 · Dataset</b><p>Ghi RGB/state/action, lọc theo QA và kết quả task.</p></article></div><div class="cp-stat-strip"><strong>1.215 <small>motion sequences</small></strong><strong>121.500 <small>robot episodes</small></strong><span>Dataset NVIDIA công bố · Sharpa · synthetic<br>${cpLink(CURRENT_PLATFORM.sources.v2dData,'Dataset card và phạm vi')}</span></div>${cpNote('Ví dụ về khả năng khai thác video người, không phải dataset G1 dùng ngay. Cần robot grounding, kiểm đơn vị/controller và QA; chi phí xử lý không bằng 0. Nhánh V2D là mở rộng, chưa tính trong ngân sách MVP Ψ₀ + SIMPLE.')}`)+cpSection('NGUỒN CHO POC','Chọn dữ liệu công khai đúng recipe',`<div class="cp-three"><article class="cp-card"><h3>EgoDex / human prior</h3><p>Video egocentric có tracking; kế thừa qua checkpoint Ψ₀ thay vì pretrain từ đầu.</p>${cpLink(CURRENT_PLATFORM.sources.ego,'EgoDex')}</article><article class="cp-card"><h3>SIMPLE / sim teleop</h3><p>Public robot demonstrations trong mô phỏng; chọn đúng task và kiểm schema.</p>${cpLink(CURRENT_PLATFORM.sources.psiData,'Dữ liệu SIMPLE')}</article><article class="cp-card"><h3>Rollout bổ sung</h3><p>Sinh trong sim quanh điều kiện lỗi do lõi Failure → Data chọn. Chỉ đưa mẫu đạt QA vào task fine-tune.</p>${cpButton('#validation','Xem các nhánh đối chứng',true)}</article></div>`)+cpV2DTools();}

/* 06 · Model Ψ₀ & training */
function cpLearning(){return cpHeader('PHẦN CẮM / MODEL Ψ₀ VÀ TRAINING','Ψ₀ kế thừa prior.<br>Đội fine-tune phần hành động.','Ψ₀ là model cắm vào lõi, không phải đóng góp của đội. Đội fine-tune trên dữ liệu teleop và dữ liệu do lõi chọn, rồi so với ACT và Diffusion Policy.')+cpFigure('psi0-architecture.png','Architecture gốc của Ψ₀: VLM, action expert và controller',CURRENT_PLATFORM.sources.psi,'Ψ₀')+cpSection('Ψ₀ GỒM GÌ','Ba tầng: kế thừa, fine-tune và bộ điều khiển',table(['Tầng','Mô tả','Vai trò trong PoC'],[['System-2','VLM Qwen3-VL-2B-Instruct, pretrain trên khoảng 829 giờ video EgoDex cùng Humanoid Everyday','Kế thừa'],['System-1','Action expert flow matching (MM-DiT), khoảng 500M tham số, dự đoán action chunk toàn thân','Fine-tune'],['System-0','Bộ điều khiển tầng thấp. Task chính trong SIMPLE chạy decoupled WBC: robot <code>g1_sonic</code>, env <code>SonicLocoManipEnv</code>, agent <code>psi0_decoupled_wbc</code>','Kế thừa; là đối tượng kiểm hệ thống ở bước 4'],['Tổng','Hơn 2,5B tham số, khoảng 160 ms mỗi lần chạy, real-time chunking','Đo VRAM và thời gian ở G0']])+cpNote('Viết “kế thừa prior video người từ Ψ₀”, không viết “platform kết hợp video người” như đóng góp của đội. Số liệu theo trang Ψ₀, kiểm ngày 22/10/2026.'))+cpSection('BỘ ĐIỀU KHIỂN / CÂU HỎI V3','WBC <code>g1_sonic</code> hay AMO: dữ liệu sinh có chạy được trong task chính?',`<div class="cp-compare"><article><span>Task chính · mọi gói *Teleop-v0</span><h3>Decoupled WBC · g1_sonic</h3><p>Teleop của <code>${CURRENT_PLATFORM.task}</code> chạy stack WBC. Lệnh gửi gồm lệnh thân trên và thân dưới; đây là giao diện mà phép kiểm bám lệnh dùng.</p>${cpLink(CURRENT_PLATFORM.sources.g1Decoupled,'Tài liệu G1 Decoupled')}</article><article><span>Pipeline motion planning · mọi gói *MP-v0</span><h3>AMO · g1_wholebody</h3><p>Trang Ψ₀ gọi AMO là System-0, nhưng trong SIMPLE đây là bộ điều khiển của pipeline MP. Rollout MP chưa chắc dùng được cho task chính.</p>${cpLink(CURRENT_PLATFORM.sources.g1Amo,'Tài liệu G1 MP (AMO)')}</article></div><div class="cp-deadline"><div><span>V3 · hạn ngày 5 của Sprint 1</span><strong>Teleop và MP có cùng bộ điều khiển, hoặc ánh xạ được?</strong><p>Nếu không: nhánh B, kiểm khả thi, trạng thái chuẩn và sinh sim chờ tuyến được chọn. Thử T1 và T2 song song tuần 1–2, chốt cuối tuần 2.</p></div></div>`+table(['Tuyến','Cách làm','Công sức','Hệ quả cho claim'],[['T1 · Tái thực thi quỹ đạo MP','Lấy quỹ đạo thân trên của rollout MP, suy lệnh thân dưới, chạy lại trong env WBC, giữ lượt thành công','1–2 tuần','Giữ thiết kế; báo tỉ lệ sinh đạt'],['T2 · Biến thể kiểu MimicGen / IntervenGen','Biến đổi đoạn teleop theo tư thế vật, chạy bằng IK cộng WBC trong env Teleop','2–3 tuần','“Sim” thành “biến thể của teleop”'],['T3 · Planner trong env WBC','Planner cho thân trên cộng lệnh cúi cho WBC','2–4 tuần','Giữ nguyên thiết kế'],['T4 · Chuyển sang env MP','Lấy task MP làm task chính, coi demo MP là demo gốc','Vài ngày','Thu hẹp claim rõ ràng; phương án cuối']]))+cpSection('ĐỘI FINE-TUNE GÌ','Cùng recipe cho mọi nhánh, chỉ khác dữ liệu',`<div class="cp-three cp-training"><article class="cp-card"><span class="cp-index">Ψ₀</span><h3>Fine-tune toàn bộ trên teleop trong miền</h3><p>Checkpoint gốc nhóm <code>pre.*</code> hoặc <code>postpre.*</code> đã qua Q0. <code>simple-checkpoints</code> và <code>sonic-checkpoints</code> chỉ dùng để tái tạo số công bố ở G0. Thiếu VRAM: LoRA hoặc đóng băng VLM, thuê A100 80 GB.</p><b>Đầu ra: policy ứng viên mỗi nhánh</b></article><article class="cp-card"><span class="cp-index">ACT · DIFFUSION POLICY</span><h3>Model nhỏ, chạy trên GPU của đội</h3><p>Trả lời câu hỏi dữ liệu sim giúp model nào nhiều nhất. ACT chạy F-ACT 5–8 vòng và các nhánh B-fail, C cho HTa, HTb.</p><b>Đầu ra: báo cáo so sánh phương pháp</b></article><article class="cp-card"><span class="cp-index">QUY TẮC CÔNG BẰNG</span><h3>Chỉ khác ở dữ liệu</h3><p>Cùng số bước S, batch, learning rate; cùng danh sách 0,7D* demo; tỉ lệ sim trong batch ρ chọn trên B rồi áp nguyên; 3 seed {0, 1, 2}; tăng cường thị giác cố định cho mọi nhánh.</p><b>Đầu ra: RunPlan chốt trước khi train</b></article></div>`+table(['Phương pháp','A','A₀.₇','B','C','B-fail'],[['Ψ₀','Có','Có','Có','Có, 1 vòng mặc định','Nếu còn ngân sách sau G4'],['Diffusion Policy','Có','Không','Có','Không','Không'],['ACT','Có','Chỉ làm π₀, 1 seed','Có','Có, từ F-ACT','Có']]))+cpSection('DỮ LIỆU → THÀNH PHẦN HỌC','Không dùng một loại nhãn cho mọi mục tiêu',table(['Dữ liệu','Dùng để học / kiểm gì?','Điều kiện'],[['Prior video người (EgoDex)','Biểu diễn thị giác–thao tác, kế thừa qua checkpoint','Không coi pose người là lệnh khớp robot'],['Teleop RGB/state/action','Hành động của robot mục tiêu','Đồng bộ, đúng thứ tự khớp và bộ điều khiển WBC'],['Rollout sim và dữ liệu do lõi chọn','Fine-tune task, phủ vùng điều kiện còn thiếu','Cùng env WBC, qua QA; dải hạt giống train và test rời nhau'],['Video dự đoán của world model','Nghiên cứu đánh giá, sau PoC','Không mặc định có joint state, lực hoặc contact']]))+cpNote('Figure mô tả phương pháp của tác giả. Việc bổ sung dữ liệu theo lỗi là cấu hình thử nghiệm của đề xuất, chưa phải kết quả được paper chứng minh cho DENSO.');}

/* 07 · PoC & bằng chứng */
const CP_BRANCHES={
 a:{label:'A',name:'Baseline',data:'D* demo teleop',question:'Cần bao nhiêu demo teleop để Ψ₀ đạt ≥ 75%? Mốc cho mọi nhánh.',versus:'Mốc của HS: B so với A',methods:'Ψ₀, Diffusion Policy, ACT',read:'D* chọn ở E1, là mức nhỏ nhất đạt ≥ 75% trên dev gộp ba mức.'},
 a07:{label:'A₀.₇',name:'Đối chứng bớt 30%',data:'0,7D* demo teleop, không bổ sung gì',question:'Bớt 30% demo thì tụt bao nhiêu? Đó là khoảng cách B và C phải lấp.',versus:'HS yêu cầu cận dưới CI 95% của (B − A₀.₇) > 0',methods:'Ψ₀; ACT chỉ làm π₀ với 1 seed',read:'Nếu A₀.₇ đã không kém A thì HS đúng nhưng không nhờ sim. A₀.₇ cũng là policy khởi đầu π₀ của nhánh C.'},
 b:{label:'B',name:'Sim rải đều',data:'0,7D* teleop + N_B rollout sim đạt QA, điều kiện lấy đều trong miền train; N_B = 2 × (D* − 0,7D*)',question:'Sim có thay được 30% demo teleop không? (HS)',versus:'So với A và A₀.₇ cho HS; là đối thủ của C (HT) và của B-fail (HTa)',methods:'Ψ₀, Diffusion Policy, ACT',read:'Chi phí thực đo để tạo đúng N_B rollout là B_add, trần chi phí thu dữ liệu của C và B-fail.'},
 bfail:{label:'B-fail',name:'Nhắm lỗi, không chẩn đoán',data:'0,7D* teleop + sim quanh mọi điều kiện lỗi dev của π₀, cùng ngân sách B_add',question:'Chỉ nhắm theo lỗi đã hơn rải đều chưa? (HTa)',versus:'HTa = B-fail − B; HTb = C − B-fail',methods:'ACT là chính; Ψ₀ nếu còn ngân sách sau G4',read:'Kiểu Mulligan rút gọn. HTa đạt mà HTb trượt: nhắm theo lỗi có ích nhưng chẩn đoán chưa đáng chi phí.'},
 c:{label:'C',name:'Failure → Data',data:'0,7D* teleop + dữ liệu do 12 bước chọn, tối đa B_add',question:'Chẩn đoán và nhiều loại can thiệp có thêm giá trị không? (HT, HTb)',versus:'C − B cho HT; C − B-fail cho HTb',methods:'Ψ₀ 1 vòng mặc định; ACT qua F-ACT 5–8 vòng',read:'Báo kèm tổng chi phí gồm chẩn đoán. Nếu C chỉ hơn B khi chưa tính chi phí chẩn đoán, báo cả hai con số.'},
 bplus:{label:'B⁺',name:'Tùy chọn',data:'0,7D* teleop + đúng tỉ lệ các loại can thiệp C đã chọn, nhưng điều kiện lấy đều',question:'Lợi ích đến từ nhắm đúng chỗ lỗi hay từ dùng nhiều loại can thiệp?',versus:'Tách “nhiều loại can thiệp” khỏi “nhắm chỗ lỗi”',methods:'Ưu tiên thấp hơn B-fail; chỉ chạy nếu còn ngân sách',read:'Bỏ B-fail hoặc B⁺ thì báo cáo phải nói rõ phần nào chưa tách được.'}
};
function cpAB(kind){const b=Object.prototype.hasOwnProperty.call(CP_BRANCHES,kind)?CP_BRANCHES[kind]:null;if(!b)throw new RangeError('Nhánh không tồn tại.');return `<div class="cp-ab-detail"><span class="cp-kicker">NHÁNH ${b.label} / ${b.name}</span><h2>${b.question}</h2><p><b>Dữ liệu train:</b> ${b.data}.</p><div class="cp-detail-grid"><div><span>So với</span><p>${b.versus}</p></div><div><span>Đọc kết quả</span><p>${b.read}</p></div><div><span>Phương pháp</span><p>${b.methods}</p></div></div></div>`;}
function cpValidation(){return cpHeader('BẰNG CHỨNG / POC TRONG MÔ PHỎNG','Các nhánh đối chứng.<br>Mỗi nhánh trả lời một câu hỏi.','PoC không chỉ hỏi “sim có thay được teleop không” mà tách được tác dụng của nhắm theo lỗi và của chẩn đoán, trên cùng ngân sách và cùng recipe.')+`<div class="cp-task"><span>Task chính trong SIMPLE</span><code>${CURRENT_PLATFORM.task}</code><p>Humanoid G1 cúi xuống gắp vật rồi đặt; gói dữ liệu teleop có trên psi-data. Task F1 (chỉ gắp) kiểm khả năng tổng quát của lõi. Bài toán DENSO thật cần ánh xạ và nghiệm thu riêng.</p></div>`+cpSection('CÁC NHÁNH','Sáu cấu hình dữ liệu, cùng checkpoint và cùng ngân sách',table(['Nhánh','Dữ liệu train','Câu hỏi trả lời'],Object.values(CP_BRANCHES).map(b=>[`<b>${b.label}</b> · ${b.name}`,b.data,b.question]))+`<section class="cp-ab"><div class="cp-choice" role="group" aria-label="Chọn nhánh để đọc kết quả">${Object.entries(CP_BRANCHES).map(([k,b],i)=>`<button type="button" data-cp-ab="${k}" aria-pressed="${i===0}" aria-controls="cp-ab-detail">${b.label}</button>`).join('')}</div><div id="cp-ab-detail" aria-live="polite">${cpAB('a')}</div><div class="cp-ab-shared"><strong>Giữ giống nhau</strong><span>Checkpoint pre.* / postpre.*</span><span>Số bước S, batch, learning rate</span><span>Danh sách 0,7D*</span><span>ρ chọn trên B</span><span>Seed {0, 1, 2}</span><span>Tăng cường thị giác cố định</span></div></section>`)+cpSection('GIẢ THUYẾT VÀ TIÊU CHÍ CHẤP NHẬN','Chốt trước khi chạy holdout',cpWide(['Mã','Giả thuyết','So sánh','Tiêu chí chấp nhận'],[['<b>HS</b>','Sim thay được 30% demo teleop','B so với A và A₀.₇ (Ψ₀)','B đạt ≥ 75% trên holdout gộp ba mức; cận dưới CI 95% của (B − A) > −10 điểm %; cận dưới CI 95% của (B − A₀.₇) > 0'],['<b>HT</b>','Nhắm theo lỗi tốt hơn bổ sung đều; kiểm lại kiểu Mulligan / DISEIL','C so với B trên Ψ₀, cùng ngân sách thu dữ liệu','Cận dưới CI 95% của (C − B) > 0, bootstrap phân cấp. Báo kèm tổng chi phí C gồm chẩn đoán, phút người và GPU-giờ riêng. MDE ở G2 > 10 điểm % mà không tăng được seed thì HT là kết quả mô tả'],['<b>HTa</b>','Nhắm theo lỗi, không chẩn đoán, tốt hơn bổ sung đều','B-fail so với B, cùng ngân sách; ACT là chính','Cận dưới CI 95% của (B-fail − B) > 0'],['<b>HTb</b>','Chẩn đoán giúp thêm ngoài việc chỉ nhắm theo lỗi','C so với B-fail, cùng ngân sách, cùng phương pháp','Cận dưới CI 95% của (C − B-fail) > 0; báo kèm chi phí chẩn đoán của C'],['<b>HD</b>','Evidence card giảm thời gian chẩn đoán','Có card so với công cụ chuẩn (Rerun cộng đồ thị mặc định)','Thời gian giảm và tỉ lệ chẩn đoán đúng không thấp hơn; r_debug báo dạng khoảng. Pilot, không phải kiểm định thống kê'],['<b>M</b>','So sánh phương pháp huấn luyện','ACT, Diffusion Policy, Ψ₀ trên A và B','Mô tả: tỉ lệ thành công theo mức, số demo để đạt 75% (kèm 80% để đối chiếu Pitch v10), chi phí train']]))+cpSection('TIÊU CHÍ 3 CẤP CỦA BTC','Mỗi cấp có chỉ tiêu đo được trong PoC',table(['Cấp BTC','Tiêu chí','Chỉ tiêu trong PoC'],[['1 · Basic','≥ 50% với lượng demo nhỏ','Báo tỉ lệ thành công ở mức 10% và 25% của đường cong E1'],['2 · Efficient','Giảm ≥ 30% demo cùng hiệu năng; ≥ 75%','HS: B ở 0,7D* không kém A và đạt ≥ 75%'],['3 · Advanced','≥ 70% trên biến thể chưa train; khuyến nghị thu dữ liệu định lượng','Level 1 và Level 2 của holdout báo riêng so với 70%, không gộp Level 0; bước 10–11 cộng sổ chi phí là khuyến nghị định lượng']]))+cpSection('D*, THỐNG KÊ VÀ F-ACT','Đủ lực thống kê trước khi kết luận',`<div class="cp-three"><article class="cp-card"><span class="cp-index">D* · NGƯỠNG 75%</span><h3>Mức demo nhỏ nhất đạt ≥ 75%</h3><p>Ψ₀ train ở 10, 25, 50, 70, 100% N_teleop; D* là mức nhỏ nhất đạt ≥ 75% trên dev gộp ba mức (thay 80% của bản trước). Chạy seed thứ hai ở hai điểm quanh ngưỡng. Trần: ≥ 90% ở mức 10% thì chuyển Level 2 hoặc task khó hơn. Sàn: dưới 60% ở 100% thì D* = N_teleop.</p></article><article class="cp-card"><span class="cp-index">THỐNG KÊ</span><h3>Holdout 150 điều kiện × 3 seed</h3><p>50 điều kiện mỗi mức × 3 mức, ghép cặp: 450 episode mỗi nhánh, chạy đúng một lần sau khi đóng băng. Chỉ số chính là cờ thành công của SIMPLE. CI 95% bằng bootstrap phân cấp 10.000 lần (seed, rồi điều kiện trong từng mức); logistic hỗn hợp để kiểm chéo. Power analysis ở G2: MDE > 10 điểm % thì thêm seed, đổi mức hoặc hạ HT thành mô tả.</p></article><article class="cp-card"><span class="cp-index">F-ACT</span><h3>Bằng chứng “flywheel học”</h3><p>5–8 vòng Failure → Data rẻ trên ACT, cùng task. Đo theo vòng: f_t và CI 95%, chi phí mỗi điểm %, thứ tự chọn so với đơn giá vòng 1, tỉ lệ ghi đè của kỹ sư. Chỉ nêu “flywheel học” khi CI của f_t hẹp dần và chi phí mỗi điểm % giảm. Kết quả ACT không chứng minh hành vi Ψ₀.</p></article></div>${cpNote('Holdout sớm và niêm phong: nhánh không phụ thuộc C chạy ngay khi đóng băng (tuần 9–10), kết quả lưu có hash, không ai xem cho tới khi C xong. Tham khảo: 50 lượt độc lập ở mức 80% có khoảng Wilson 95% khoảng 67%–89%; đó là lý do bỏ cách đo “≥ 80% / 50 lượt” của Pitch v10.')}`)+cpSection('QUY TẮC DIỄN GIẢI','Kết quả âm cũng là kết quả',`<div class="cp-compare"><article><span>HS và HT kết luận độc lập</span><h3>HT trượt vẫn phải báo</h3><p>Khi đó giá trị còn lại là Data Core, sổ chi phí và khuyến nghị thu dữ liệu định lượng; pitch phải bỏ claim “nhắm lỗi thắng rải đều”.</p></article><article><span>Đọc HTa và HTb cùng nhau</span><h3>Tách nguồn của lợi ích</h3><p>HTa trượt mà HTb đạt: lợi ích đến từ chẩn đoán và nhiều loại can thiệp, không từ việc nhắm theo lỗi. Ứng viên bị từ chối và vòng không cải thiện đều giữ trong báo cáo cùng chi phí.</p></article></div><div class="cp-source-links">${cpLink(CURRENT_PLATFORM.sources.psiCode,'Code Ψ₀')}${cpLink(CURRENT_PLATFORM.sources.simple,'Simulator SIMPLE')}${cpLink(CURRENT_PLATFORM.sources.psiData,'psi-data / simple')}${cpLink(CURRENT_PLATFORM.sources.rerun,'Rerun · công cụ chuẩn cho HD')}</div>`);}

/* 08 · Giá trị & chi phí */
function cpNetFormula(rDemo,rDebug){return 500*rDemo+400*rDebug-181.8;}
function cpBusiness(){const c=cpEvaluateCost(),sens=[[0.3,0.5,'30%','50%','Kịch bản Pitch v10'],[0.3,0,'30%','0%','Không giảm được giờ debug'],[181.8/500,0,'khoảng 36%','0%','Điểm hòa vốn khi không giảm debug'],[0.5,0,'50%','0%','Giảm nhiều demo, không giảm debug'],[0.3,0.25,'30%','25%','Giảm debug một nửa so với pitch']];
 return cpHeader('BẰNG CHỨNG / GIÁ TRỊ VÀ CHI PHÍ','Dẫn bằng giờ người và số ngày.<br>Đô-la chỉ là kịch bản.','Báo cáo kinh tế lấy số từ sổ chi phí và holdout. Công thức đô-la của Pitch v10 giữ lại để đối chiếu, kèm độ nhạy và hai điểm yếu phải nói thẳng. Chưa có số đo tại DENSO.')+cpSection('CHỈ SỐ GIÁ TRỊ CHÍNH','Năm con số báo cáo cho DENSO',`<div class="cp-value-grid">${[['01','Số demo người để đạt ngưỡng','Teleop cộng correction để đạt 75%, theo phương pháp và theo nhánh.'],['02','Phút operator mỗi điểm % tăng thêm','Theo nhánh và theo loại can thiệp.'],['03','Chi phí mỗi điểm % của C so với B và B-fail','(Chi phí C gồm chẩn đoán − chi phí nhánh đối chiếu) ÷ (thành công C − nhánh đối chiếu). CI mẫu số chứa 0 thì ghi “không xác định”.'],['04','Sai số dự báo chi phí','(Ước tính − thực đo) / thực đo cho từng can thiệp, từ cờ trong sổ.'],['05','Số ngày để đạt lại ngưỡng','Sau khi đổi điều kiện, ví dụ đổi khay hoặc ánh sáng.']].map(v=>`<article><b>${v[0]}</b><h3>${v[1]}</h3><p>${v[2]}</p></article>`).join('')}</div>${cpNote('HT báo kèm hai ràng buộc riêng: số phút người và số GPU-giờ mà B, B-fail và C đã dùng. “Cùng ngân sách USD” phụ thuộc tỉ giá giữa giờ người và GPU-giờ.')}`)+cpSection('CÔNG THỨC RÚT GỌN CỦA PITCH V10','Lợi ích ròng mỗi đợt phụ thuộc r_demo và r_debug',`<div class="cp-formula"><div><span>Lợi ích ròng mỗi đợt cải thiện (USD)</span><strong>500 × r_demo + 400 × r_debug − 181,80</strong><small>$500: thu và QA teleop của baseline · $400: debug của baseline · $181,80: chi phí tăng thêm (GPU sinh sim $14,80, QA sim và tích hợp $160, lưu trữ thêm $7)</small></div></div>`+table(['r_demo','r_debug','Lợi ích ròng / đợt','Ghi chú'],sens.map(s=>[s[2],s[3],`<b>${cpUsd(cpNetFormula(s[0],s[1]))}</b>`,s[4]]))+`<div class="cp-sensitive"><strong>Hai điểm yếu phải nói thẳng</strong><span>Không có số hạng nào cho HT: r_demo đến từ HS, r_debug đến từ HD. Lõi chọn theo lỗi không đóng góp đô-la nào trong công thức này.</span><span>Với r_demo = 30%, hòa vốn chỉ cần r_debug khoảng 8% ((181,80 − 150) / 400), nên “có lãi” gần như chắc chắn. Vì vậy r_debug lấy dạng khoảng từ HD, lợi ích báo theo cận dưới và cận trên.</span></div>`)+cpSection('ĐỘ NHẠY THEO ĐƠN GIÁ','Chi phí giờ cell có thể đổi kết luận',table(['Kịch bản','Operator','Chi phí giờ cell','Đơn giá GPU','Mục đích'],[['Pitch v10','$10/h','$0','A100 $1,59/h · RTX 4090 $0,74/h','Đối chiếu với pitch'],['DENSO','Đơn giá DENSO','Chi phí giờ cell DENSO','Như trên','Kịch bản chính khi DENSO gửi số'],['Cell đắt','$10/h','$100/h, giả định kiểm độ nhạy','Như trên','Khi chi phí cell lớn hơn hẳn nhân công'],['GPU đắt','$10/h','$0','Gấp đôi','Khi GPU thuê đắt hoặc khan']])+cpNote('Chi phí giờ cell (robot, người giám sát, thời gian dừng dây chuyền) áp cho mọi phút teleop, correction và reset. Với mỗi kịch bản, tính lại chi phí mỗi điểm % và xem kết luận HT có đổi chiều không.'))+`<section class="cp-cost-controls"><div class="cp-flow-head"><div>${cpKicker('KỊCH BẢN PITCH V10')}<h2>Máy tính kịch bản Pitch v10</h2></div><span class="cp-status">Không phải kết quả đo</span></div><form id="cp-cost-form" novalidate><div class="cp-form-grid"><label>Số đợt đạt nghiệm thu / năm<input name="cycles" type="number" value="144" min="0" max="10000" step="1" required></label><label>Giảm demo gốc (%)<input name="reduction" type="number" value="30" min="0" max="100" step="1" required></label><label>Debug candidate (giờ / đợt)<input name="debugAfter" type="number" value="10" min="0" max="10000" step="0.5" required></label><label>Operator (USD / giờ)<input name="operator" type="number" value="10" min="0" max="10000" step="0.5" required></label><label>Kỹ sư (USD / giờ)<input name="engineer" type="number" value="20" min="0" max="10000" step="0.5" required></label></div><div class="cp-cost-bottom"><label><input name="quality" type="checkbox" checked> Chỉ xét kịch bản đã đạt cùng chất lượng nghiệm thu</label><button type="reset" class="cp-reset">Về giả định của slide</button></div><p id="cp-cost-error" role="alert" hidden></p></form><p class="cp-hint">Kịch bản Pitch v10: baseline 200 demo gốc, yield 80%, debug 20 giờ; 144 đợt/năm chưa có cơ sở tại DENSO. Giả định chất lượng ở trên là điều kiện tính toán, không xác nhận PoC đã đạt.</p></section><section id="cp-cost-results" aria-live="polite" aria-label="Kết quả ước lượng chi phí">${cpCostResults(c)}</section>`+cpSection('R1 / R2 / A1','Nguồn giá và công thức baseline',`<div class="cp-three"><article class="cp-card"><b>R1 · GPU Runpod</b><p>A100 PCIe 80GB: <strong>$1.59/GPU-h</strong><br>RTX 4090: <strong>$0.74/GPU-h</strong></p>${cpLink(CURRENT_PLATFORM.sources.price,'Bảng giá Runpod')}<small>Giá lưu trong slide, kiểm 08/10/2026. Cần xác nhận khi thuê.</small></article><article class="cp-card"><b>R2 · Storage Runpod</b><p>Network volume dưới 1TB:<br><strong>$0.07/GB-tháng</strong></p>${cpLink(CURRENT_PLATFORM.sources.storage,'Cách tính storage')}<small>Scratch mỗi đợt giữ 1 tháng. Archive chung nằm trong OPEX năm.</small></article><article class="cp-card"><b>A1 · Giả định nội bộ mô hình</b><p>Operator $10/h; kỹ sư $20/h.<br>Yield 80%; thu/reset 6 phút; QA 3 phút/lượt.</p><small>Chưa là báo giá teleop/robotics hoặc baseline DENSO; chưa tính chi phí giờ cell.</small></article></div><details class="cp-details"><summary>Xem phép tính từng khoản và những gì chưa đưa vào</summary><p>250/175 lượt thu = 200/140 demo gốc ÷ yield 80%. Thu/reset: 25/17,5h × $10 = $250/$175. QA: 12,5/8,75h × $20 = $250/$175. Debug: 20/10h × $20 = $400/$200.</p><p>Cả hai: 120h train + 20h eval A100 = $222.60. Candidate thêm: 20h RTX 4090 = $14.80; QA synthetic 6h + tích hợp 2h kỹ sư = $160; scratch tăng $7. Giảm công $350 − chi phí thêm $181.80 = <b>$168.20/đợt</b>.</p><p>140 A100-giờ mỗi đợt phải kiểm lại theo số đo ở G0. Không pretrain human từ đầu, không triển khai V2D/DreamDojo trong PoC tính tiền này. Bổ sung mua robot/camera, adaptation, bảo mật, license, thuế và downtime nếu phát sinh.</p><p>72/144 đợt là kịch bản chưa xác nhận tại DENSO. Giá trị công tiết kiệm chỉ thành tiết kiệm tiền mặt khi thực sự giảm ngân sách hoặc có giá trị sử dụng công được xác nhận.</p></details><a href="data/current-cost-model.json" download>Tải mô hình và giả định gốc ↓</a>`);}

/* 09 · Lộ trình 12 tuần */
function cpRoles(){return cpWide(['Người','Vai chính','Dự phòng','Dự phòng cho'],CURRENT_PLATFORM.roles.map(r=>[`<b>${esc(r.name)}</b>`,r.role,r.backup,r.covers]));}
function cpRoadmap(){return cpHeader('TRIỂN KHAI / LỘ TRÌNH 12 TUẦN','Sáu sprint, bảy cổng.<br>Mỗi cổng có điều kiện đi tiếp.','Lập kế hoạch ở 70% năng lực, 30% còn lại là đệm. Ngày theo giả định bắt đầu thứ Hai 26/10/2026; bắt đầu ngày khác thì dời cả lịch, giữ thứ tự.')+`<div class="cp-deadline"><div><span>V3 · hạn ngày 5 của Sprint 1</span><strong>Teleop (WBC g1_sonic) và MP (AMO) có cùng bộ điều khiển?</strong><p>Thứ Sáu 30/10/2026 theo lịch giả định. Nếu âm: thử T1 và T2 song song, chốt tuyến cuối tuần 2.</p></div><div><span>Q0 · trước cổng G0</span><strong>Checkpoint gốc chưa thấy dữ liệu task chính?</strong><p>Chọn <code>pre.*</code> hoặc <code>postpre.*</code> đã xác nhận với PSI Lab; chưa xác nhận thì dùng <code>pre.*</code> và ghi giới hạn vào báo cáo.</p></div></div><ol class="cp-roadmap cp-sprints">${CURRENT_PLATFORM.milestones.map(m=>`<li><span class="cp-road-no">${m.sprint}</span><div><span class="cp-sprint-meta">${m.weeks} · ${m.dates}</span><h2>${m.gate}</h2><p><span>Việc chính</span>${m.work}</p><p><span>Điều kiện đi tiếp</span>${m.exit}</p></div></li>`).join('')}</ol>`+cpSection('NGUYÊN TẮC LẬP KẾ HOẠCH','Bốn quyết định để kịp 12 tuần',`<div class="cp-four">${['Lập kế hoạch ở 70% năng lực; 30% là đệm cho việc chưa biết','Lát dọc trên SIMPLE trước tuần 4: trace thật → scorer → evidence card → sổ chi phí','Mặc định 1 vòng C cho Ψ₀; các vòng thêm chạy trên ACT (F-ACT)','Holdout sớm, niêm phong cho nhánh không phụ thuộc C; tuần 11 chỉ còn holdout của C'].map((s,i)=>`<div class="cp-small-card"><b>0${i+1}</b><strong>${s}</strong></div>`).join('')}</div>`)+cpSection('AI LÀM GÌ','Vai chính và người dự phòng',cpRoles()+cpNote('Kế hoạch triển khai ghi rõ: ở 20 giờ mỗi người mỗi tuần, phạm vi mặc định vượt mức kế hoạch 70%; thứ tự cắt việc đã duyệt chưa đủ bù. Quyết định phạm vi chốt ở buổi lập kế hoạch Sprint 1. Hiếu ký cổng và duyệt đề xuất vòng C, không là người review duy nhất của PR nào.'))+`<section class="cp-next-gate">${cpIcon('robot')}<div><h2>Sau G6: nghiệm thu robot thật là cổng riêng</h2><p>Bộ điều khiển và calibration phù hợp → kiểm an toàn, binding và task → real2sim cho cell → đối chứng thực địa với DENSO. Ngoài phạm vi PoC.</p></div></section>`;}

/* 10 · Mở rộng L0 → L4 */
function cpOutcomes(){const levels=[['L0','PoC · 12 tuần','1 task, 1 robot, trong sim','Ψ₀ + SIMPLE / G1; ACT, Diffusion Policy để so sánh','Mô hình dữ liệu, scorer, chẩn đoán, sổ chi phí chạy được cho 1 recipe'],['L1','Nhiều task','3–5 task cùng robot, trong sim','Định nghĩa task và vị từ scorer cho từng task mới','Thư viện scorer theo loại task; thống kê can thiệp dùng chung giữa task qua “lớp lỗi chung”; dùng dữ liệu lỗi để train'],['L2','Robot thật','1 cell thật','Adapter robot thật, teleop thật, an toàn','Real2sim cho tình huống lỗi; cổng nghiệm thu robot thật; chi phí giờ cell trong sổ'],['L3','Nhiều robot','Nhiều embodiment','Adapter model đa robot','Chuẩn hóa schema state/action theo embodiment'],['L4','Nhiều nhà máy','Nhiều đội dùng chung','Lưu trữ tập trung','Phân quyền, nhiều người dùng, báo cáo theo đơn vị']];
 return cpHeader('TRIỂN KHAI / MỞ RỘNG L0 → L4','Lõi giữ nguyên.<br>Adapter thay theo từng mức.','Thiết kế lõi trong 12 tuần chỉ cần chạy ở L0, nhưng mô hình dữ liệu và giao diện adapter phải đúng cho L1–L3 để không phải viết lại.')+`<div class="cp-core-strip"><strong>Lõi giữ nguyên</strong>${['Mô hình dữ liệu','Lineage, QA, chia tập','Khung scorer','Chuỗi chẩn đoán + bảng quyết định','Chọn can thiệp + tỉ lệ sửa được','Sổ chi phí + cổng kiểm'].map(s=>`<span>${s}</span>`).join('')}</div><ol class="cp-ladder">${levels.map(l=>`<li><b>${l[0]}</b><div><h3>${l[1]}</h3><p>${l[2]}</p></div><div><span>Adapter đổi</span><p>${l[3]}</p></div><div><span>Lõi cần thêm</span><p>${l[4]}</p></div></li>`).join('')}</ol>${cpNote('Khả năng mở rộng là đề xuất. Chưa có bằng chứng triển khai nhiều task, nhiều robot hay nhiều nhà máy DENSO. Tỉ lệ sửa được dùng chung giữa task là tài sản cần đo ở L1, chưa phải lợi thế đã có.')}`+cpSection('ĐIỀU KIỆN BẮT ĐẦU PILOT','Bốn đầu vào cần phối hợp với DENSO',`<div class="cp-four">${['Một kỹ năng và người phụ trách công đoạn','Video / demo tham chiếu được phép sử dụng','Đơn giá operator, chi phí giờ cell, số task mỗi năm','Layout, ràng buộc trạm làm việc và thông số robot ứng viên'].map((s,i)=>`<div class="cp-small-card"><b>0${i+1}</b><strong>${s}</strong></div>`).join('')}</div>`);}
function cpEvaluateCost(overrides={}){
 const a={...CURRENT_COST_MODEL.assumptions,...overrides};
 for(const [k,v] of Object.entries(a))if(typeof v!=='number'||!Number.isFinite(v)||v<0)throw new RangeError('Giả định phải là số không âm: '+k);
 if(a.yield<=0||a.yield>1||a.rootsAfter>a.rootsBefore)throw new RangeError('Yield phải >0 và ≤1; demo candidate không vượt baseline.');
 const cycles=overrides.cycles??144;if(!Number.isInteger(cycles))throw new RangeError('Số đợt phải là số nguyên.');
 const captureQA=r=>r/a.yield*(a.captureMin/60*a.operator+a.qaMin/60*a.engineer);
 const gpu=(a.mainA100h+a.evalA100h)*a.a100;
 const rows=[['Thu + QA teleop',captureQA(a.rootsBefore),captureQA(a.rootsAfter)],['Debug / phân tích lỗi',a.debugBefore*a.engineer,a.debugAfter*a.engineer],['GPU train, eval, sinh sim',gpu,gpu+a.sim4090h*a.rtx4090],['QA synthetic + tích hợp',0,(a.syntheticQAh+a.integrationh)*a.engineer],['Scratch storage / 1 tháng',a.storageBeforeGB*a.storage,a.storageAfterGB*a.storage]];
 const before=rows.reduce((s,r)=>s+r[1],0),after=rows.reduce((s,r)=>s+r[2],0),net=before-after;
 const setup=80*a.engineer+20*a.a100+200*a.storage,pilot=before+after,initial=setup+pilot,opex=48*a.engineer+500*12*a.storage;
 const steady=net*cycles-opex,firstYear=steady-initial;
 return {a,rows,before,after,net,setup,pilot,initial,opex,cycles,steady,firstYear,roi:initial?firstYear/initial*100:null,threshold:net>0?Math.floor((20000+opex)/net)+1:null,firstThreshold:net>0?Math.floor((20000+opex+initial)/net)+1:null};
}
function cpCostResults(c,eligible=true){return `<div class="cp-cost-total"><div><span>Baseline / đợt</span><strong>${cpMoney(c.before)}</strong></div><span>→</span><div><span>Đề xuất / đợt</span><strong>${cpMoney(c.after)}</strong></div><div class="${c.net>=0?'cp-saving':'cp-negative'}"><span>Ròng / đợt</span><strong>${eligible?cpMoney(c.net):'Chưa đủ điều kiện'}</strong></div></div>${table(['USD / một lần cải thiện task','Baseline','Đề xuất'],[...c.rows.map(r=>[r[0],cpMoney(r[1]),cpMoney(r[2])]),['<b>Tổng</b>',`<b>${cpMoney(c.before)}</b>`,`<b>${cpMoney(c.after)}</b>`]])}<div class="cp-metrics">${cpMetric(eligible?cpMoney(c.steady):'—','Năm ổn định',`${c.cycles} đợt đạt nghiệm thu, trừ OPEX chung`)}${cpMetric(eligible?cpMoney(c.firstYear):'—','Năm đầu','Trừ thêm đầu tư và pilot đối chứng')}${cpMetric(eligible&&c.roi!==null?cpNumber(c.roi)+'%':'—','ROI năm đầu','Lợi ích năm đầu / đầu tư ban đầu')}</div><p class="cp-note">${eligible?(c.net>0?`Để vượt $20.000: cần ≥${c.threshold} đợt/năm ổn định hoặc ≥${c.firstThreshold} đợt năm đầu, nếu giữ nguyên các giả định.`:'Kịch bản này không tạo tiết kiệm ròng mỗi đợt. Không có ngưỡng số đợt giúp vượt $20.000.'): 'Chưa đạt cùng chất lượng: không ghi nhận lợi ích hoặc ROI. Chi phí A/B vẫn phát sinh.'}</p><details class="cp-details"><summary>Đầu tư ban đầu, OPEX và công thức năm</summary><p>Setup: 80 giờ kỹ sư + 20 A100-h + 200 GB-tháng = <b>${cpMoney(c.setup)}</b>.<br>Pilot A + B = <b>${cpMoney(c.pilot)}</b>. Đầu tư ban đầu = <b>${cpMoney(c.initial)}</b>.<br>OPEX chung: 48 giờ kỹ sư/năm + 500 GB × 12 tháng = <b>${cpMoney(c.opex)}/năm</b>.</p><p>Năm ổn định = ròng/đợt × số đợt − OPEX chung.<br>Năm đầu = năm ổn định − đầu tư ban đầu. Số đợt sinh lợi không tính cặp pilot trong đầu tư.</p></details>`;}
/* 11 · Đội thực hiện */
function cpTeam(){return cpHeader('ĐỘI THỰC HIỆN','<span class="cp-team-name">ilovephysicalintelligence</span>','5 thành viên, 3 mảng chuyên môn để thực hiện PoC humanoid gắp–đặt. Video VLA và mã RL bên dưới là các dự án trước đây của đội.')+`<div class="cp-team-grid">${CURRENT_PLATFORM.team.map((t,i)=>`<article class="cp-team-card"><div class="cp-team-top"><span>0${i+1}</span><b>${t.area}</b></div><h2>${t.names.map(esc).join('<br>')}</h2><p>${t.skills}</p>${t.affiliation?`<p class="cp-affiliation">${t.affiliation}</p>`:''}<div class="cp-team-output"><span>Đầu ra PoC dự kiến</span><strong>${t.output}</strong></div><p class="${i===0?'cp-proof-available':'cp-proof-pending'}">${t.status}</p><small>${t.proof}</small>${i===0?`<div class="cp-source-links">${cpLink(CURRENT_PLATFORM.teamEvidence[0].sourceUrl,'Video VLA')}${cpLink(CURRENT_PLATFORM.teamEvidence[1].sourceUrl,'Repo RL')}</div>`:''}</article>`).join('')}</div><div class="cp-team-owner"><strong>Đầu mối chốt công đoạn và nghiệm thu: Dương Đình Hiếu</strong><p>Phối hợp với task owner DENSO, BTC và mentor. Người phụ trách xác nhận bảng công và hiệu quả cần chốt khi bắt đầu pilot.</p></div>`+cpSection('VAI TRONG KẾ HOẠCH 12 TUẦN','Ai giữ phần nào của lõi và adapter',cpRoles()+cpNote('Châu dự phòng cho hai người (Hiếu ở việc Ψ₀ và Hưng); bù bằng runbook Ψ₀ từ Sprint 2. Mảng Simulation và Data vẫn chờ bổ sung minh chứng; tuyến T3 (planner trong env WBC) chưa có minh chứng của mảng Simulation.'))+cpTeamEvidence()+cpSection('MINH CHỨNG BỔ SUNG','Gắn kết quả với người thực hiện',`<div class="cp-three"><article class="cp-plain"><b>Robot Learning</b><p>Đã có video VLA và repo RL. Bổ sung config, log, checkpoint và phần việc cụ thể của từng người.</p></article><article class="cp-plain"><b>Simulation</b><p>Video cảnh chạy task; robot/controller, dữ liệu xuất và phần Hưng/Châu đảm nhiệm.</p></article><article class="cp-plain"><b>Data / Platform</b><p>Mẫu trước/sau xử lý; schema, báo cáo QA và phần Long/Thông thực hiện.</p></article></div>${cpNote('Minh chứng có thể để trên Drive với quyền xem. Những dự án trước đây cho thấy kinh nghiệm liên quan; kết quả PoC Ψ₀ + SIMPLE và hiệu quả tại DENSO cần được kiểm chứng riêng.')}`);}

/* 12 · Nguồn & tiền lệ (gộp nội dung DreamDojo cũ) */
function cpResearch(){const s=CURRENT_PLATFORM.sources;return cpHeader('THAM KHẢO / NGUỒN VÀ TIỀN LỆ','Công nghệ có sẵn.<br>Tiền lệ đã kiểm.','Hình và phương pháp thuộc các tác giả gốc. Kết quả của paper không được coi là kết quả đo của đội. Các link kiểm ngày 22/10/2026.')+`<div class="cp-three"><article class="cp-card"><span class="cp-status">Model</span><h2>Ψ₀</h2><p>VLM + action expert + bộ điều khiển; checkpoint trên Hugging Face chưa có thẻ model và giấy phép, vai trò từng thư mục cần tác giả xác nhận (Q0).</p><div class="cp-source-links">${cpLink(s.psi,'Trang dự án')}${cpLink(s.psiCode,'Mã nguồn')}${cpLink(s.psiModel,'Checkpoint')}</div></article><article class="cp-card"><span class="cp-status">Simulator</span><h2>SIMPLE</h2><p>Isaac Sim 4.5 và MuJoCo 3.3, robot Unitree G1, hơn 50 cảnh; bộ đánh giá ba mức: Level 0 trong miền, Level 1 thêm ánh sáng mạnh, Level 2 thêm đổi vị trí vật.</p><div class="cp-source-links">${cpLink(s.simple,'Repo')}${cpLink(s.simpleDocs,'Tài liệu')}</div></article><article class="cp-card"><span class="cp-status">Dữ liệu</span><h2>psi-data / simple</h2><p>18 gói, hai kiểu <code>*Teleop-v0</code> và <code>*MP-v0</code>; gói task chính 108 MB. Không có gói MP trùng đúng task chính.</p><div class="cp-source-links">${cpLink(s.psiData,'psi-data')}${cpLink(s.ego,'EgoDex')}</div></article></div>`+cpSection('TIỀN LỆ FAILURE → DATA','Mỗi thành phần đều có tiền lệ; đóng góp là cách ghép và phép đo',cpWide(['Tiền lệ','Đã làm gì','Quan hệ với đề xuất'],[[cpLink(s.mulligan,'Mulligan (2026)'),'Chọn trạng thái đầu của mỗi vòng thu dữ liệu tại các lỗi đã thấy và trạng thái chưa thử; dùng cả dữ liệu lỗi để học value function','HT kiểm lại kiểu này trên G1 toàn thân; B-fail là “kiểu Mulligan rút gọn”; dùng dữ liệu lỗi để train là hướng L1'],[cpLink(s.diseil,'DISEIL (2026)'),'Tìm điểm policy bắt đầu không tin cậy, gom lỗi thành nhóm, chọn lỗi cần expert làm mẫu, kiểm khả thi trước khi tốn công expert','Gần nhất với bước 3 và 5; đề xuất thêm kiểm hệ thống và thước đo chi phí gồm chẩn đoán'],[`${cpLink(s.dagger,'DAgger')} · ${cpLink(s.hgdagger,'HG-DAgger')}`,'Thu correction của chuyên gia trên trạng thái do policy tạo ra','Teleop correction (KỸ NĂNG YẾU) và dữ liệu phục hồi (TRẠNG THÁI ĐẦU XẤU)'],[cpLink(s.intervengen,'IntervenGen (2024)'),'Sinh correction hàng loạt từ ít can thiệp của người','Tuyến T2 khi V3 âm; dữ liệu phục hồi do máy sinh khi không có thiết bị teleop'],[cpLink(s.mimicgen,'MimicGen'),'Sinh biến thể trong sim từ một ít demo gốc','Tuyến T2; biến thể luôn trỏ về episode cha, không đếm là demo gốc'],[`${cpLink(s.datamil,'DataMIL')} · ${cpLink(s.cupid,'CUPID (2025)')}`,'Chọn demo bằng influence function','Tiền lệ cho bước chọn dữ liệu; đề xuất không claim cách chọn mới']])+cpNote('Trong phạm vi đã tra ngày 22/10/2026, chưa thấy quy trình kiểm hệ thống trước rồi chọn giữa nhiều loại can thiệp (sinh sim, correction, dữ liệu phục hồi) bằng một thước đo tiền và giờ công gồm cả chi phí chẩn đoán. So sánh chi tiết ở trang 03.'))+cpSection('HƯỚNG MỞ RỘNG / NVIDIA V2D','Video công nhân DENSO → dữ liệu robot, sau PoC',`<div class="cp-compare"><article><span>Đầu vào → đầu ra</span><h3>Video người → tái dựng → grounding → dữ liệu robot</h3><p>Là một bộ sinh dữ liệu cắm vào lõi (phần cắm), không nằm trong ngân sách PoC. Cần cổng nghiệm thu riêng: robot grounding, kiểm đơn vị và bộ điều khiển, QA.</p>${cpButton('#sources','Xem input / output ở trang 05',true)}</article><article><span>Nguồn</span><h3>Toolkit và tutorial</h3><div class="cp-source-links">${cpLink(s.v2d,'V2D · toolkit và tài liệu')}${cpLink(s.v2dRepo,'Repo V2D')}${cpLink(s.v2dTutorial,'CoRL tutorial')}</div></article></div>`)+cpSection('HƯỚNG MỞ RỘNG / DREAMDOJO','Dự đoán video tương lai. Action được đưa vào từ đầu.',`<p class="cp-hint">DreamDojo là nhánh mở rộng cho đánh giá và lập kế hoạch sau PoC. Recipe Ψ₀ + SIMPLE và lõi Failure → Data không phụ thuộc nhánh này.</p><div class="cp-io"><div><span>INPUT</span><h2>Quan sát đầu<br>+ action robot</h2><p>Chuỗi hành động điều kiện được cung cấp.</p></div><div class="cp-model">DreamDojo<br><small>World model</small></div><div><span>OUTPUT</span><h2>Video tương lai</h2><p>Chuỗi RGB dự đoán phản ứng theo action.</p></div></div>`+cpFigure('dreamdojo-overview.png','DreamDojo: human video pretraining, robot post-training, distillation và ứng dụng',s.dream,'DreamDojo')+table(['Dataset nhánh này có thể lưu','Cần nguồn riêng'],[['Quan sát đầu + action điều kiện + future RGB','Joint state ground truth'],['Phiên bản generator, điều kiện sinh và lineage','Lực, contact và kết quả robot thật'],['Video dự đoán để nghiên cứu đánh giá policy','Nhãn action mới nếu chưa được cung cấp hoặc suy ra có kiểm chứng']])+cpNote('Video nhìn hợp lý không chứng minh task thực thi thành công. Nghiệm thu vẫn dùng simulator hoặc robot và scorer độc lập.'))+cpDreamDatasetExplanation()+cpSection('PHẠM VI BẰNG CHỨNG','Ba mức cần phân biệt',table(['Mức','Hiện có','Không suy ra'],[['Nguồn công khai','Paper, code, checkpoint, dataset','Đội đã tái lập kết quả tác giả'],['Tiền lệ','Mulligan, DISEIL và các phương pháp chọn hoặc sinh dữ liệu','Nhắm theo lỗi là điểm mới của đội'],['PoC đề xuất','Spec v10.1 với nhánh, giả thuyết và tiêu chí chốt trước holdout','Đã đạt mục tiêu hay có ROI thực tế']]))+cpNote('Bản PowerPoint Pitch v10 chưa cập nhật theo spec v10.1. Khi hai nguồn lệch nhau, website và spec v10.1 là bản đúng; pitch sẽ cập nhật sau khi có kết quả G6.');}

/* Router entry: every page shares the story bar, bridge line, source line and pager. */
function renderCurrentPlatform(id){const routes={overview:cpOverview,product:cpProduct,architecture:cpArchitecture,engine:cpEngine,sources:cpSources,learning:cpLearning,validation:cpValidation,business:cpBusiness,roadmap:cpRoadmap,outcomes:cpOutcomes,team:cpTeam,research:cpResearch};if(!Object.prototype.hasOwnProperty.call(routes,id))return null;const m=CP_PAGE_META[id];return `<div class="cp-page" data-current-presentation="spec-v10.1" data-cp-part="${cpPartOf(id).id}">${cpStoryBar(id)}${cpBridge(id)}${routes[id]()}${m.src?`<p class="cp-source-line">Nguồn: spec v10.1 ${m.src}</p>`:''}${cpPager(id)}</div>`;}
function cpTeamEvidence(){return cpSection('DỰ ÁN TRƯỚC ĐÂY CỦA ĐỘI','Kinh nghiệm đã thực hiện',`<div class="cp-evidence-grid">${CURRENT_PLATFORM.teamEvidence.map(e=>{const c=e.crop;const cropStyle=`--proof-width:${100*c.sourceWidth/c.width}%;--proof-height:${100*c.sourceHeight/c.height}%;--proof-left:${-100*c.x/c.width}%;--proof-top:${-100*c.y/c.height}%`;return `<article class="cp-evidence-card" data-team-evidence="${e.id}"><div class="cp-evidence-media" style="${cropStyle}"><img src="assets/team/${e.image}" alt="${e.imageAlt}" loading="lazy">${e.embedUrl?`<button type="button" data-cp-team-video="${e.id}" aria-label="Phát video FOCA trên SmolVLA">▶ Xem video</button>`:''}</div><div class="cp-evidence-content"><span class="cp-kicker">${e.subtitle}</span><h3>${e.title}</h3><dl class="cp-evidence-metrics">${e.metrics.map(m=>`<div><dt>${m[0]}</dt><dd>${m[1]}</dd></div>`).join('')}</dl><p>${e.summary}</p><p class="cp-evidence-relevance">${e.relevance}</p><div class="cp-source-links">${cpLink(e.sourceUrl,e.embedUrl?'Mở video trên Drive':'Xem mã nguồn')}${e.codeUrl?cpLink(e.codeUrl,'Script training · revision đã xem'):''}${e.folderUrl?cpLink(e.folderUrl,'Thư mục minh chứng'):''}</div><p class="cp-evidence-scope">${e.scope}</p><details><summary>Phạm vi minh chứng và thông tin cần bổ sung</summary><p>${e.detail}</p></details></div></article>`;}).join('')}</div>`);}
function initCPTeamEvidence(signal){main.querySelectorAll('[data-cp-team-video]').forEach(button=>button.addEventListener('click',()=>{const e=CURRENT_PLATFORM.teamEvidence.find(x=>x.id===button.dataset.cpTeamVideo);if(!e?.embedUrl)return;const frame=document.createElement('iframe');frame.src=e.embedUrl;frame.title='Video training và inference FOCA trên SmolVLA do đội cung cấp';frame.allow='autoplay; fullscreen';frame.allowFullscreen=true;frame.referrerPolicy='strict-origin-when-cross-origin';const media=button.closest('.cp-evidence-media');media.classList.add('cp-evidence-playing');media.replaceChildren(frame);},{once:true,signal}));}
function initCurrentPlatform(signal){
 main.querySelectorAll('[data-cp-step]').forEach(b=>b.addEventListener('click',()=>{main.querySelectorAll('[data-cp-step]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));main.querySelector('#cp-step-detail').innerHTML=cpStepDetail(Number(b.dataset.cpStep));},{signal}));
 main.querySelectorAll('[data-cp-fault]').forEach(b=>b.addEventListener('click',()=>{main.querySelectorAll('[data-cp-fault]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));main.querySelector('#cp-fault-result').innerHTML=cpFault(b.dataset.cpFault);},{signal}));
 main.querySelectorAll('[data-cp-ab]').forEach(b=>b.addEventListener('click',()=>{main.querySelectorAll('[data-cp-ab]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));main.querySelector('#cp-ab-detail').innerHTML=cpAB(b.dataset.cpAb);},{signal}));
 const form=main.querySelector('#cp-cost-form');if(form){const result=main.querySelector('#cp-cost-results'),error=main.querySelector('#cp-cost-error');function update(){error.hidden=true;if(!form.checkValidity()){error.textContent='Nhập đủ giá trị trong giới hạn; số đợt/năm phải là số nguyên không âm.';error.hidden=false;result.innerHTML='<p class="cp-note">Chưa thể tính: cần sửa giả định không hợp lệ.</p>';return;}try{const f=form.elements,c=cpEvaluateCost({cycles:Number(f.cycles.value),rootsAfter:CURRENT_COST_MODEL.assumptions.rootsBefore*(1-Number(f.reduction.value)/100),debugAfter:Number(f.debugAfter.value),operator:Number(f.operator.value),engineer:Number(f.engineer.value)});result.innerHTML=cpCostResults(c,f.quality.checked);}catch(e){error.textContent=e.message;error.hidden=false;result.innerHTML='';}}
 form.addEventListener('input',update,{signal});form.addEventListener('submit',e=>e.preventDefault(),{signal});form.addEventListener('reset',e=>{e.preventDefault();for(const input of form.querySelectorAll('input')){if(input.type==='checkbox')input.checked=input.defaultChecked;else input.value=input.defaultValue;}update();},{signal});}
 if(main.querySelector('#cp-dataset-gallery'))initCPDatasetGallery(signal);if(main.querySelector('[data-cp-team-video]'))initCPTeamEvidence(signal);
}

function cpDatasetExamples(){return cpSection('EXAMPLE / DỮ LIỆU CÓ THỂ XEM VÀ KIỂM','Xem video. Đọc tín hiệu thật.',`<section id="cp-dataset-gallery" class="cp-dataset-gallery"><p class="cp-hint">Chọn một mẫu để xem video/hình và dữ liệu đi kèm. Đây là nguồn công khai của tác giả, không phải dữ liệu DENSO hoặc kết quả PoC của đội.</p><div class="cp-dataset-choices" role="group" aria-label="Chọn ví dụ dataset">${CURRENT_PLATFORM.datasetExamples.map((d,i)=>`<button type="button" data-cp-dataset="${d.id}" aria-pressed="${i===0}" aria-controls="cp-dataset-body"><strong>${d.label}</strong><small>${d.kind}</small></button>`).join('')}</div><div id="cp-dataset-body">${cpDatasetBody('human')}</div></section>`);}
function cpDatasetBody(id){
 const preview=(name,label)=>`<a href="data/${name}.json" target="_blank" rel="noopener">${label} · JSON ↗</a>`;
 if(id==='human')return `<div class="cp-example-intro"><h3>HumanEgo / Aria · serve_bread_000</h3><p>Human ego RGB và 1.002 tracking rows của tay. Wrist pose là tín hiệu người, chưa phải robot joint action.</p></div><div class="inspector-layout">${media('humanTracking')}<section class="panel inspector" id="human-inspector"><p>Đang đọc mẫu tracking…</p></section></div>${cpNote('Tracking thiếu phải giữ null + validity mask, không coi [0,0,0] là pose thật. Preview không giả đồng bộ từng frame video–tracking. HumanEgo data: CC BY-NC 4.0; cần kiểm quyền dùng khi triển khai thương mại.')}<div class="cp-source-links">${preview('humanego-hands','Tracking đã trích')}${cpLink(MEDIA.humanTracking.source,'Dataset nguồn')}</div><details class="cp-details"><summary>Xem thêm video minh họa cách thu human ego</summary>${media('human')}<p>Video collection minh họa riêng của tác giả, không ghép thành cặp thời gian với tracking serve_bread_000 ở trên.</p></details>`;
 if(id==='g1')return `<div class="cp-example-intro"><h3>Unitree G1 / Dex3 · toasted bread</h3><p>Teleop robot thật. Episode 0: 620 frames, 30fps, 28 state và 28 action values/frame. Chọn khớp hoặc frame để đọc dữ liệu.</p></div><div class="inspector-layout">${media('g1')}<section class="panel inspector" id="robot-inspector"><p>Đang đọc state/action…</p></section></div>${cpNote('Đây là mẫu G1 thật để hiểu schema, không phải task SIMPLE đang chọn cho PoC. Video pin revision; numeric preview Rows API chưa đối chiếu bitwise với pinned parquet. Chưa xác minh căn từng frame video; chưa có force/contact trong preview.')}<div class="cp-source-links">${preview('g1-episode-0','620 rows state/action')}${cpLink(MEDIA.g1.source,'Dataset Unitree')}</div>`;
 if(id==='gr1')return `<div class="cp-example-intro"><h3>RoboCasa GR1 · đặt chai vào tủ, đóng cửa</h3><p>Demonstration humanoid trong mô phỏng. RGB ego, 29 state và 29 action dimensions; episode 0 có 376 frames ở 20fps.</p></div><div class="inspector-layout">${media('gr1').replace('Task household có waist unlocked; khác task khay fixed-torso của proposal.','Ví dụ GR1 trong sim; không phải dataset G1/SIMPLE của PoC.')}<section class="panel inspector" id="gr1-inspector"><p>Đang đọc 6 rows từ parquet…</p></section></div>${cpNote('Numeric trích từ parquet pin revision; không gọi đây là real-robot teleop hoặc rollout policy của đội. Preview row và player được chọn độc lập. Nguồn NVIDIA/RoboCasa CC BY-NC 4.0.')}<div class="cp-source-links">${preview('gr1-preview','Metadata + 6 rows')}${cpLink(MEDIA.gr1.source,'Dataset GR1')}</div>`;
 if(id==='libero')return `<div class="cp-example-intro"><h3>LIBERO / Panda · đặt hai cốc lên đĩa</h3><p>Demonstration trong sim. Episode 0: 214 frames ở 10fps; state 8 chiều, action 7 chiều. Không phải humanoid.</p></div><div class="inspector-layout">${media('libero')}<section class="panel inspector" id="libero-inspector"><p>Đang đọc numeric preview…</p></section></div>${cpNote('Chỉ 6 rows đầu trong inspector; không tự chạy số theo video. Numeric Rows API chưa đối chiếu bitwise với pinned parquet. Số chiều khác nhau cần mapping/controller phù hợp trước khi dùng cho robot khác.')}<div class="cp-source-links">${preview('libero-preview','Metadata + 6 rows')}${cpLink(MEDIA.libero.source,'Dataset LIBERO')}</div>`;
 if(id==='mimicgen')return `<div class="cp-example-intro"><h3>MimicGen · từ seed demonstrations đến biến thể trong sim</h3><p>Xem seed và các tình huống được tạo thêm. Nhãn robot đến từ rollout thực thi trong simulator, cần lọc thành công và QA.</p></div><div class="media-grid">${media('simSeed')}${media('sim')}</div>${cpNote('Ví dụ của tác giả MimicGen để hiểu logic synthetic physics; không phải kết quả đã chạy Ψ₀/SIMPLE của đội. Biến thể không được đếm thành các demo gốc độc lập.')}`;
 if(id==='dreamgen')return `<div class="cp-example-intro"><h3>DreamGen · video được sinh và policy rollout</h3><p>Hai video là hai loại bằng chứng khác nhau. DreamGen là phương pháp riêng, không phải DreamDojo.</p></div><div class="media-grid">${media('dream')}${media('dreamPolicy')}</div>${cpNote('Không suy ra video synthetic tự chứa đủ state/action/force/contact. Các kết quả thuộc tác giả; không phải rollout DENSO hoặc bằng chứng DreamDojo đã tạo dataset hoàn chỉnh.')}<div class="cp-actions">${cpButton('#research','DreamDojo sinh được những gì?',true)}</div>`;
 throw new RangeError('Ví dụ dataset không tồn tại.');
}
function cpV2DTools(){return cpSection('TOOLKIT SỬ DỤNG / NVIDIA VIDEO TO DATA','Các công cụ để biến video thành dữ liệu robot',`<div class="cp-source-links cp-tool-links">${cpLink(CURRENT_PLATFORM.sources.v2dRepo,'GitHub · nvidia-isaac/video_to_data')}${cpLink(CURRENT_PLATFORM.sources.v2dTutorial,'CoRL tutorial · From Human Videos to Dexterous Robot Capability')}</div>${table(['Bước','Tool / thành phần','Input → output'],CURRENT_PLATFORM.v2dTooling)}<div class="cp-three"><article class="cp-plain"><b>Kiểm video và hình học</b><p>Clip đúng thao tác; depth/mask/mesh/pose hợp lý, scale và thời gian khớp.</p></article><article class="cp-plain"><b>Kiểm khả thi robot</b><p>Retarget đúng embodiment, support/contact hợp lý; rollout vượt scorer.</p></article><article class="cp-plain"><b>Kiểm dataset huấn luyện</b><p>Đúng action/state schema, có nguồn gốc, tách train/test và lưu QA.</p></article></div><details class="cp-details"><summary>Đọc đúng vai trò repo và tutorial</summary><p>Repo cung cấp các gói ingestion, reconstruction và robotic grounding. Chạy từng stage, kiểm artifact rồi mới nối pipeline. Tutorial tổ chức tương tự: video truy xuất được → reconstruction hợp lý → robot-facing assets/motion → policy training/evaluation trong Isaac Lab.</p><p>Trang tutorial mô tả hướng laptop inspection, chạy GPU và precomputed artifacts; danh sách materials có mục sẽ công bố sau tutorial. Không mặc định mọi notebook/artifact đã tải được. Đối chiếu README và pin revision trước khi triển khai.</p><p>Đây là nhánh mở rộng V2D. Mô hình chi phí và recipe PoC hiện hành vẫn là Ψ₀ + SIMPLE; không cộng ngầm pipeline V2D vào ngân sách.</p></details>`);}
function cpDreamDatasetExplanation(){return cpSection('CÂU HỎI / SYNTHETIC DATA ĐẦY ĐỦ?','Có thể tạo dữ liệu để học, nhưng cần xác định nhãn.',`<div class="cp-compare"><article><span>DREAMDOJO TỰ SINH</span><h3>Video phản ứng theo action</h3><p>Quan sát đầu + action từ teleop/policy → chuỗi RGB dự đoán. Có thể lưu cặp RGB/action điều kiện để nghiên cứu augmentation hoặc đánh giá.</p></article><article><span>CẦN BỔ SUNG CHO POLICY</span><h3>State, nhãn vật lý và QA</h3><p>Không tự có joint state kế tiếp, force/contact hoặc reward/success được đo. Policy cần state phải có mô hình trạng thái, simulator hoặc phép đo phù hợp.</p></article></div>${cpNote('Action điều kiện không phải action mới được DreamDojo tự gán nhãn từ một video người bất kỳ. Post-training cần dữ liệu robot mục tiêu; latent action học từ video người không đồng nghĩa lệnh khớp robot.')}<div class="cp-ledger">Ví dụ + action có sẵn <span>→</span> DreamDojo dự đoán RGB <span>→</span> thêm state/nhãn còn thiếu <span>→</span> QA <span>→</span> thử train policy <span>→</span> test trong sim/robot</div><p class="cp-hint">Đây là thiết kế tích hợp đề xuất, không phải tính năng tạo dataset hoàn chỉnh được repo bảo đảm. RGB/action tổng hợp có thể hữu ích, nhưng cải thiện robot learning phải kiểm thực nghiệm. Paper thử policy một camera không dùng proprioceptive state để đánh giá trong world model; không tự nhiên hỗ trợ multi-view.</p><div class="cp-source-links">${cpLink(CURRENT_PLATFORM.sources.dreamCode,'DreamDojo · code chính thức')}${cpLink(CURRENT_PLATFORM.sources.dreamPaper,'Paper · phương pháp và downstream applications')}</div>`);}
function initCPDatasetGallery(signal){
 const root=main.querySelector('#cp-dataset-gallery'),body=root.querySelector('#cp-dataset-body');let child=new AbortController();signal.addEventListener('abort',()=>child.abort(),{once:true});
 function show(id){child.abort();child=new AbortController();root.querySelectorAll('[data-cp-dataset]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.cpDataset===id)));body.innerHTML=cpDatasetBody(id);initMedia(body,child.signal);if(id==='human'||id==='g1')initSamples(child.signal);if(id==='gr1')initGR1(child.signal);if(id==='libero')initLibero(child.signal);}
 root.querySelectorAll('[data-cp-dataset]').forEach(b=>b.addEventListener('click',()=>show(b.dataset.cpDataset),{signal}));show('human');
}
